// Auto-generated by tools/build_studio_bundles.py
window.STUDIO_DIALOGUE_BUNDLE = [{"id": "HatchlingCompanion.gd:564:%DRAGON%", "kind": "dialogue", "region": "Golden Hatchling Companion", "file": "scripts/companions/HatchlingCompanion.gd", "line": 564, "speaker": "%DRAGON%", "portrait": "portrait_boy_neutral.png", "telepathic": true, "text": "line_text"}, {"id": "AnnaSanctuaryCh1Region.gd:93:Virelai", "kind": "dialogue", "region": "Anna Sanctuary Council (Book II)", "file": "scripts/regions/AnnaSanctuaryCh1Region.gd", "line": 93, "speaker": "Virelai", "portrait": "portrait_virelai.png", "telepathic": false, "text": "Captain—Kestrel dropped in from Old Heverlee half-frozen with brass blood-scrolls strapped to her ankle."}, {"id": "AnnaSanctuaryCh1Region.gd:94:Captain Anna", "kind": "dialogue", "region": "Anna Sanctuary Council (Book II)", "file": "scripts/regions/AnnaSanctuaryCh1Region.gd", "line": 94, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Read it twice and keep your voice low before Hendrick catches wind. We'll point the Council toward the sea and clear the river convoy ourselves."}, {"id": "AnnaSanctuaryCh1Region.gd:140:Captain Anna", "kind": "dialogue", "region": "Anna Sanctuary Council (Book II)", "file": "scripts/regions/AnnaSanctuaryCh1Region.gd", "line": 140, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "\"Inquisitors murdered his parents at Old Heverlee... Clara captive at Namur Quarry... live dragon hearts drained for an iron ritual.\""}, {"id": "AnnaSanctuaryCh1Region.gd:141:Captain Anna", "kind": "dialogue", "region": "Anna Sanctuary Council (Book II)", "file": "scripts/regions/AnnaSanctuaryCh1Region.gd", "line": 141, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Easy, Kestrel girl—catch your breath beside Matthijs's fire before we send supplies back west."}, {"id": "AnnaSanctuaryCh1Region.gd:147:Saddler Hendrick", "kind": "dialogue", "region": "Anna Sanctuary Council (Book II)", "file": "scripts/regions/AnnaSanctuaryCh1Region.gd", "line": 147, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Our cliff patrol rides north for the coast at once—no Church tracker will trace an egg down the inland canals while I hold Council seal!"}, {"id": "AnnaSanctuaryCh1Region.gd:203:Saddler Hendrick", "kind": "dialogue", "region": "Anna Sanctuary Council (Book II)", "file": "scripts/regions/AnnaSanctuaryCh1Region.gd", "line": 203, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "I'll dispatch three scout pairs westward before sunrise—nobody hides a loose egg on my cliffs!"}, {"id": "AnnaSanctuaryCh1Region.gd:204:Captain Anna", "kind": "dialogue", "region": "Anna Sanctuary Council (Book II)", "file": "scripts/regions/AnnaSanctuaryCh1Region.gd", "line": 204, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "line"}, {"id": "AnnaSanctuaryCh1Region.gd:223:Saddler Matthijs", "kind": "dialogue", "region": "Anna Sanctuary Council (Book II)", "file": "scripts/regions/AnnaSanctuaryCh1Region.gd", "line": 223, "speaker": "Saddler Matthijs", "portrait": "portrait_matthijs.png", "telepathic": false, "text": "Double-oiled rations, hemp splices, and flint stowed neat on Kestrel's flank-pack—light enough for high gale winds."}, {"id": "AnnaSanctuaryCh1Region.gd:224:Captain Anna", "kind": "dialogue", "region": "Anna Sanctuary Council (Book II)", "file": "scripts/regions/AnnaSanctuaryCh1Region.gd", "line": 224, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Mount up with me at the cliff edge once Hendrick walks clear—there's a Church blood-convoy chaining barges upriver tonight."}, {"id": "AnnaSanctuaryCh1Region.gd:230:Captain Anna", "kind": "dialogue", "region": "Anna Sanctuary Council (Book II)", "file": "scripts/regions/AnnaSanctuaryCh1Region.gd", "line": 230, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Throw Hendrick off the scent first before we lift off—if he guesses Brabant, he'll send riders after my nephew."}, {"id": "BrabantFensRegion.gd:267:%DRAGON%", "kind": "dialogue", "region": "Brabant Reed-Fens (Book II)", "file": "scripts/regions/BrabantFensRegion.gd", "line": 267, "speaker": "%DRAGON%", "portrait": "portrait_boy_neutral.png", "telepathic": true, "text": "Warm... snapping embers right down in my throat! Look—orange soot sparks!"}, {"id": "BrabantFensRegion.gd:273:%PLAYER%", "kind": "dialogue", "region": "Brabant Reed-Fens (Book II)", "file": "scripts/regions/BrabantFensRegion.gd", "line": 273, "speaker": "%PLAYER%", "portrait": "portrait_boy17.png", "telepathic": false, "text": "Wait—did you just throw your voice straight inside my head? Hush then, little one."}, {"id": "BrabantFensRegion.gd:278:%PLAYER%", "kind": "dialogue", "region": "Brabant Reed-Fens (Book II)", "file": "scripts/regions/BrabantFensRegion.gd", "line": 278, "speaker": "%PLAYER%", "portrait": "portrait_boy17.png", "telepathic": false, "text": "My parents walked Louvain's Hunters' Guild before Old Heverlee killed them. Guild ledgers or Church vaults beyond that wall should still name where they took Clara."}, {"id": "BrabantFensRegion.gd:283:%DRAGON%", "kind": "dialogue", "region": "Brabant Reed-Fens (Book II)", "file": "scripts/regions/BrabantFensRegion.gd", "line": 283, "speaker": "%DRAGON%", "portrait": "portrait_boy_neutral.png", "telepathic": true, "text": "Heavy iron sluice bars seal the bridge road ahead... though that low drain grate beside them looks plenty wide for soot-black claws. And dry dead brambles south smell ready for one hot spark."}, {"id": "BrabantFensRegion.gd:432:%PLAYER%", "kind": "dialogue", "region": "Brabant Reed-Fens (Book II)", "file": "scripts/regions/BrabantFensRegion.gd", "line": 432, "speaker": "%PLAYER%", "portrait": "portrait_boy17.png", "telepathic": false, "text": "Easy now, Kestrel... you carried us miles south of Bruges before first watch even changed. Those old millstones out in the mist—we've reached the fens west of Louvain."}, {"id": "BrabantFensRegion.gd:437:%PLAYER%", "kind": "dialogue", "region": "Brabant Reed-Fens (Book II)", "file": "scripts/regions/BrabantFensRegion.gd", "line": 437, "speaker": "%PLAYER%", "portrait": "portrait_boy17.png", "telepathic": false, "text": "You can't stay hunkered in these reeds till sunrise. If Captain Anna finds your perch empty at dawn, Saddler Hendrick will turn every parish road in Brabant upside down looking for us."}, {"id": "BrabantFensRegion.gd:442:%PLAYER%", "kind": "dialogue", "region": "Brabant Reed-Fens (Book II)", "file": "scripts/regions/BrabantFensRegion.gd", "line": 442, "speaker": "%PLAYER%", "portrait": "portrait_boy17.png", "telepathic": false, "text": "Get back above the clouds while the dark still covers your wings. I have to find what my parents died hiding near Old Heverlee, and keep this black-and-gold egg out of any iron vault. I'll hail Anna's forward scouts from quiet campfires once it's safe."}, {"id": "BrabantFensRegion.gd:548:%PLAYER%", "kind": "dialogue", "region": "Brabant Reed-Fens (Book II)", "file": "scripts/regions/BrabantFensRegion.gd", "line": 548, "speaker": "%PLAYER%", "portrait": "portrait_boy17.png", "telepathic": false, "text": "Dark as bog iron, yet traced across crest and wing-bone in living gold... All right then, %s—let's carve a warm bite by these coals first."}, {"id": "BrabantFensRegion.gd:589:Milepost & Church Notice", "kind": "dialogue", "region": "Brabant Reed-Fens (Book II)", "file": "scripts/regions/BrabantFensRegion.gd", "line": 589, "speaker": "Milepost & Church Notice", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "\"WALL OF LOUVAIN — WEST DIKE GATE. BY ORDER OF THE INQUISITION: Twenty golden florins for any black-and-gold wyrmling or carrier seized inside Brabant parish walls. All riders inspect harnesses at the tollhouse.\""}, {"id": "BrabantFensRegion.gd:601:%PLAYER%", "kind": "dialogue", "region": "Brabant Reed-Fens (Book II)", "file": "scripts/regions/BrabantFensRegion.gd", "line": 601, "speaker": "%PLAYER%", "portrait": "portrait_boy17.png", "telepathic": false, "text": "Hold up—crimson Church lanterns beyond that gate arch! Twenty gold florins on a black-and-gold wyrmling."}, {"id": "BrabantFensRegion.gd:606:%DRAGON%", "kind": "dialogue", "region": "Brabant Reed-Fens (Book II)", "file": "scripts/regions/BrabantFensRegion.gd", "line": 606, "speaker": "%DRAGON%", "portrait": "portrait_boy_neutral.png", "telepathic": true, "text": "Tuck me tight inside your wool cloak-sling across your ribs—claws hidden till we clear their watch!"}, {"id": "BrabantFensRegion.gd:703:%PLAYER%", "kind": "dialogue", "region": "Brabant Reed-Fens (Book II)", "file": "scripts/regions/BrabantFensRegion.gd", "line": 703, "speaker": "%PLAYER%", "portrait": "portrait_boy17.png", "telepathic": false, "text": "Only cold soot-dust... your belly's still empty after that freezing flight. Let's carve warm ration by the fire first."}, {"id": "BrugesCityMapData.gd:389:tf_steens_burgher", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 389, "speaker": "Master Draper", "portrait": "portrait_watchman.png", "telepathic": false, "text": "Church riders stopped two wool scows before noon. Cloth-Factor Joris up by Grote Markt Cloth Hall saw their coin-purses up close.", "npc_id": "tf_steens_burgher", "tex": "npc_city_burgher"}, {"id": "BrugesCityMapData.gd:395:tf_market_fishwife", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 395, "speaker": "Goodwife Trude", "portrait": "portrait_maren.png", "telepathic": false, "text": "Fresh Zwin plaice, half-salt! Sister Beatrijs in the Beguinage east was brewing sleep-draughts for Church men, and a black wagon rolled west toward the Counting-House Wharf.", "npc_id": "tf_market_fishwife", "tex": "npc_city_fishwife"}, {"id": "BrugesCityMapData.gd:401:tf_beguine_walker", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 401, "speaker": "Beguine Sister", "portrait": "portrait_maren.png", "telepathic": false, "text": "Quiet footsteps inside the garden close, child. Sister Beatrijs by the Apothecary knows what those hooded riders loaded onto their wagon.", "npc_id": "tf_beguine_walker", "tex": "npc_city_apothecary"}, {"id": "BrugesCityMapData.gd:407:tf_cloister_monk", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 407, "speaker": "Cloister Brother", "portrait": "portrait_priest.png", "telepathic": false, "text": "Cathedral porch stands locked and empty until evening vespers at the eighth hour. Not a priest stirs before dusk falls.", "npc_id": "tf_cloister_monk", "tex": "npc_city_monk"}, {"id": "BrugesCityMapData.gd:413:tf_wharf_porter", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 413, "speaker": "Wharf Porter", "portrait": "portrait_quartermaster.png", "telepathic": false, "text": "Keep wide of that iron-chain wagon parked below the Counting-House! Armed Catchpoles in black cloaks have been hovering round its tailgate all afternoon.", "npc_id": "tf_wharf_porter", "tex": "npc_city_cooper"}, {"id": "BrugesCityMapData.gd:419:tf_citadel_guard", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 419, "speaker": "Citadel Patrol", "portrait": "portrait_watchman.png", "telepathic": false, "text": "Move along, boy—princely business inside the bailey. Only clergy and Inquisitor's escorts stay past curfew.", "npc_id": "tf_citadel_guard", "tex": "npc_city_guard"}, {"id": "BrugesCityMapData.gd:425:tf_south_gate_guard", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 425, "speaker": "South Gate Watch", "portrait": "portrait_watchman.png", "telepathic": false, "text": "Portcullis drops at third dusk horn! Keep your business inside Steenstraat or clear the moat bridge now.", "npc_id": "tf_south_gate_guard", "tex": "npc_city_guard"}, {"id": "BrugesCityMapData.gd:431:tf_spiegelrei_weaver", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 431, "speaker": "Loom Apprentice", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "My master says the bishop's clerk bought out every bolt of heavy canvas along the Spiegelrei!", "npc_id": "tf_spiegelrei_weaver", "tex": "npc_city_apprentice"}, {"id": "BrugesCityMapData.gd:438:tf_gate_left", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 438, "speaker": "Gate Pikeman", "portrait": "portrait_watchman.png", "telepathic": false, "text": "Keep hands visible past the South Barbican, lad.", "npc_id": "tf_gate_left", "tex": "npc_city_guard"}, {"id": "BrugesCityMapData.gd:439:tf_citadel_south", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 439, "speaker": "Bailiff Guard", "portrait": "portrait_watchman.png", "telepathic": false, "text": "No rabble loitering under the Citadel South Gate!", "npc_id": "tf_citadel_south", "tex": "npc_city_guard"}, {"id": "BrugesCityMapData.gd:440:tf_baker_wife", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 440, "speaker": "Baker's Wife", "portrait": "portrait_maren.png", "telepathic": false, "text": "Last rye batch just cooled—if those hooded priests leave us a copper worth of flour.", "npc_id": "tf_baker_wife", "tex": "npc_city_fishwife"}, {"id": "BrugesCityMapData.gd:441:tf_cloth_boy", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 441, "speaker": "Cloth Runner", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Factor Joris has been swearing over Church cloth orders since noon—says Sister Beatrijs in the Beguinage knows where the riders hauled it!", "npc_id": "tf_cloth_boy", "tex": "npc_city_apprentice"}, {"id": "BrugesCityMapData.gd:442:tf_cooper_quay", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 442, "speaker": "Barrelmaker", "portrait": "portrait_quartermaster.png", "telepathic": false, "text": "Tarred casks for brine and tallow—don't touch that iron-chain church wagon by the Counting-House unless you want Catchpoles on your back.", "npc_id": "tf_cooper_quay", "tex": "npc_city_cooper"}, {"id": "BrugesCityMapData.gd:443:tf_sailor_barge", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 443, "speaker": "Barge Skipper", "portrait": "portrait_shipmaster.png", "telepathic": false, "text": "Watergate chains rattle all evening. Something heavy is sitting on that wagon below the Counting-House.", "npc_id": "tf_sailor_barge", "tex": "npc_city_sailor"}, {"id": "BrugesCityMapData.gd:444:tf_tavern_patron", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 444, "speaker": "Swan Patron", "portrait": "portrait_watchman.png", "telepathic": false, "text": "Swan's tap is cold but tongues are hotter—ask Factor Joris or the Beguine sisters what Church carts rolled across Guildhall Bridge.", "npc_id": "tf_tavern_patron", "tex": "npc_city_burgher"}, {"id": "BrugesCityMapData.gd:445:tf_cathedral_novice", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 445, "speaker": "Novice Clerk", "portrait": "portrait_priest.png", "telepathic": false, "text": "St. Donatian's steps stand empty till the eighth evening bell—none of the priests cross the courtyard before curfew.", "npc_id": "tf_cathedral_novice", "tex": "npc_city_monk"}, {"id": "BrugesCityMapData.gd:446:tf_ropewalk_hand", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 446, "speaker": "Ropewalk Braider", "portrait": "portrait_shipmaster.png", "telepathic": false, "text": "Clara used to whip better bowlines than half the masters here... pray she's safe.", "npc_id": "tf_ropewalk_hand", "tex": "npc_city_sailor"}, {"id": "BrugesCityMapData.gd:447:tf_beguine_herb", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityMapData.gd", "line": 447, "speaker": "Herb Gatherer", "portrait": "portrait_maren.png", "telepathic": false, "text": "Valerian and poppy-sap gone before supper—Sister Beatrijs looks grim as winter.", "npc_id": "tf_beguine_herb", "tex": "npc_city_apothecary"}, {"id": "BrugesCityRegion.gd:540:Dropped Ambush Note", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 540, "speaker": "Dropped Ambush Note", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "\"...the hollow nest was cold and the egg already taken. Meet Father Anselm at St. Donatian's by the eighth evening bell...\""}, {"id": "BrugesCityRegion.gd:544:Factor Joris", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 544, "speaker": "Factor Joris", "portrait": "portrait_baker.png", "telepathic": false, "text": "West across Guildhall Bridge by the Counting-House Wharf—that's where the Catchpoles' mud-spattered iron wagon rolled to. Ask Sister Beatrijs east in the Beguinage too if you want her herbal tally."}, {"id": "BrugesCityRegion.gd:550:Factor Joris", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 550, "speaker": "Factor Joris", "portrait": "portrait_baker.png", "telepathic": false, "text": "Linen wagons halted at the Cloth Hall gate since noon! Black-cloak Catchpoles rode in from the eastern border woods, paying bishop's gold coin for oilcloth wraps and tallow search-lanterns."}, {"id": "BrugesCityRegion.gd:551:Factor Joris", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 551, "speaker": "Factor Joris", "portrait": "portrait_baker.png", "telepathic": false, "text": "They're shutting every gate to search cellars and canal barges for something stolen from the wilds—picked up sleeping-draughts from Sister Beatrijs in the Beguinage, then rolled their iron-chain wagon west over Guildhall Bridge to the Counting-House Wharf."}, {"id": "BrugesCityRegion.gd:556:Sister Beatrijs", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 556, "speaker": "Sister Beatrijs", "portrait": "portrait_maren.png", "telepathic": false, "text": "West across the canal bridges, beside the Counting-House Wharf—that guarded Catchpole wagon holds what you're looking for. Mind their bolts."}, {"id": "BrugesCityRegion.gd:562:Sister Beatrijs", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 562, "speaker": "Sister Beatrijs", "portrait": "portrait_maren.png", "telepathic": false, "text": "Church Catchpoles back from the border woods bought half the Beguinage's sleeping-draughts and search-torches! Muttered of an empty nest in a scorched hollow and locking Bruges down till what was taken is found."}, {"id": "BrugesCityRegion.gd:563:Sister Beatrijs", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 563, "speaker": "Sister Beatrijs", "portrait": "portrait_maren.png", "telepathic": false, "text": "Cloth-Factor Joris at Grote Markt saw their gold coin, and the guarded iron-chain wagon itself is parked west across the canal outside the Counting-House Wharf."}, {"id": "BrugesCityRegion.gd:568:Catchpole Sergeant", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 568, "speaker": "Catchpole Sergeant", "portrait": "portrait_watchman.png", "telepathic": false, "text": "Hey! Hands off the Inquisitor's search-wain, gutter-rat! Shields up—pin him against the wharf!"}, {"id": "BrugesCityRegion.gd:685:Church Inquisitor", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 685, "speaker": "Church Inquisitor", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "Our hunters reached the border hollow where our bolts brought the black dragon down. Did they destroy its nest?"}, {"id": "BrugesCityRegion.gd:686:Father Anselm", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 686, "speaker": "Father Anselm", "portrait": "portrait_priest.png", "telepathic": false, "text": "The beast was lying dead in the ash, Inquisitor—but its nest was cold and empty. Someone carried the egg away before our men arrived."}, {"id": "BrugesCityRegion.gd:687:Church Inquisitor", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 687, "speaker": "Church Inquisitor", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "That egg was never meant to see the light of day! Seal every canal gate in Bruges before dawn."}, {"id": "BrugesCityRegion.gd:688:Father Anselm", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 688, "speaker": "Father Anselm", "portrait": "portrait_priest.png", "telepathic": false, "text": "At first light, cry a silver bounty on anyone seen carrying a pitch-black egg veined with gold. Coin will make every burgher in Flanders our eyes."}, {"id": "BrugesCityRegion.gd:699:Church Inquisitor", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 699, "speaker": "Church Inquisitor", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "There—behind the keep pillar! Catchpoles, shut the yard and bring me that spy alive!"}, {"id": "BrugesCityRegion.gd:717:South Gatehouse Post", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 717, "speaker": "South Gatehouse Post", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "v PORT OF BRUGES — Outer Docks, Warehouse & Ropewalk Quarter"}, {"id": "BrugesCityRegion.gd:721:East Gatehouse Post", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 721, "speaker": "East Gatehouse Post", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "-> COASTAL OUTSKIRTS & SANCTUARY TRAIL across the East Moat"}, {"id": "BrugesCityRegion.gd:745:String(src[\"id\"])", "kind": "bark", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 745, "speaker": "String(src[\"name\"])", "portrait": "portrait_watchman.png", "telepathic": false, "text": "String(src.get(\"bark\"", "npc_id": "String(src[\"id\"])", "tex": "String(src[\"tex\"])"}, {"id": "BrugesCityRegion.gd:780:String(tf[\"name\"])", "kind": "dialogue", "region": "Walled Bruges City (Ch. 4)", "file": "scripts/regions/BrugesCityRegion.gd", "line": 780, "speaker": "String(tf[\"name\"])", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "bark"}, {"id": "BrugesOutskirtsRegion.gd:205:title_str", "kind": "dialogue", "region": "Bruges Outskirts (Ch. 4)", "file": "scripts/regions/BrugesOutskirtsRegion.gd", "line": 205, "speaker": "title_str", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "body_str"}, {"id": "BrugesOutskirtsRegion.gd:212:Tollkeeper", "kind": "dialogue", "region": "Bruges Outskirts (Ch. 4)", "file": "scripts/regions/BrugesOutskirtsRegion.gd", "line": 212, "speaker": "Tollkeeper", "portrait": "portrait_narrator.png", "telepathic": false, "text": "msg"}, {"id": "CustomDungeonHazards.gd:95:String(n.get(\"speaker\"", "kind": "dialogue", "region": "CustomDungeonHazards", "file": "scripts/regions/CustomDungeonHazards.gd", "line": 95, "speaker": "String(n.get(\"speaker\"", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "zt"}, {"id": "CustomDungeonHazards.gd:250:%DRAGON%", "kind": "dialogue", "region": "CustomDungeonHazards", "file": "scripts/regions/CustomDungeonHazards.gd", "line": 250, "speaker": "%DRAGON%", "portrait": "portrait_hatchling_stage1.png", "telepathic": true, "text": "The water is still and cold. Nothing more to mend."}, {"id": "CustomDungeonHazards.gd:262:String(n.get(\"speaker\"", "kind": "dialogue", "region": "CustomDungeonHazards", "file": "scripts/regions/CustomDungeonHazards.gd", "line": 262, "speaker": "String(n.get(\"speaker\"", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "ln"}, {"id": "CustomDungeonHazards.gd:272:%DRAGON%", "kind": "dialogue", "region": "CustomDungeonHazards", "file": "scripts/regions/CustomDungeonHazards.gd", "line": 272, "speaker": "%DRAGON%", "portrait": "portrait_hatchling_stage1.png", "telepathic": true, "text": "A heavy lock. Somewhere in these halls there is a %s that fits it."}, {"id": "CustomDungeonRegion.gd:527:String(n.get(\"speaker\"", "kind": "dialogue", "region": "CustomDungeonRegion", "file": "scripts/regions/CustomDungeonRegion.gd", "line": 527, "speaker": "String(n.get(\"speaker\"", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "String(n.get(\"text\""}, {"id": "CustomDungeonRegion.gd:541:%DRAGON%", "kind": "dialogue", "region": "CustomDungeonRegion", "file": "scripts/regions/CustomDungeonRegion.gd", "line": 541, "speaker": "%DRAGON%", "portrait": "portrait_hatchling_stage1.png", "telepathic": true, "text": "An iron ward still seals this reliquary lock—something in the chamber must unlatch it first."}, {"id": "CustomDungeonRegion.gd:554:%PLAYER%", "kind": "dialogue", "region": "CustomDungeonRegion", "file": "scripts/regions/CustomDungeonRegion.gd", "line": 554, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Claimed %s from the chamber reliquary!"}, {"id": "FrontierWildsRegion.gd:727:Anna", "kind": "dialogue", "region": "Frontier Wilds (Ch. 3)", "file": "scripts/regions/FrontierWildsRegion.gd", "line": 727, "speaker": "Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "%s? We swept three ridges searching every fern brake for your coat—wait. What are you cradling inside your sling?"}, {"id": "FrontierWildsRegion.gd:728:%PLAYER%", "kind": "dialogue", "region": "Frontier Wilds (Ch. 3)", "file": "scripts/regions/FrontierWildsRegion.gd", "line": 728, "speaker": "%PLAYER%", "portrait": "portrait_boy_angry.png", "telepathic": false, "text": "Don't look at me like I turned soft on beasts. Church bolts crippled the black one out in the hollow—I just wasn't leaving a live thing in the dirt to freeze."}, {"id": "FrontierWildsRegion.gd:729:Anna", "kind": "dialogue", "region": "Frontier Wilds (Ch. 3)", "file": "scripts/regions/FrontierWildsRegion.gd", "line": 729, "speaker": "Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Black-scaled...? Bring it inside by the stone hearth before the chill settles through the shell. Tomorrow we talk."}, {"id": "LouvainCatacombsRegion.gd:376:%PLAYER%", "kind": "dialogue", "region": "Louvain Catacombs (Book II)", "file": "scripts/regions/LouvainCatacombsRegion.gd", "line": 376, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "An ancient ruby-sealed Brotherhood vial and fresh ash pellets tucked under the Prior's Chalice slab!"}, {"id": "LouvainCatacombsRegion.gd:377:%DRAGON%", "kind": "dialogue", "region": "Louvain Catacombs (Book II)", "file": "scripts/regions/LouvainCatacombsRegion.gd", "line": 377, "speaker": "%DRAGON%", "portrait": "portrait_hatchling_stage1.png", "telepathic": true, "text": "Your pulse just grew steadier—and those ash-flasks carry clean beeswax seals."}, {"id": "LouvainCatacombsRegion.gd:494:West Tapestry — Of the Stag", "kind": "dialogue", "region": "Louvain Catacombs (Book II)", "file": "scripts/regions/LouvainCatacombsRegion.gd", "line": 494, "speaker": "West Tapestry — Of the Stag", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "\"Four Stags guard these cold rows, yet three keep only the outer walls. Seek the solitary Stag in the inner bays—born directly south of a Chalice and directly east of a Crown.\""}, {"id": "LouvainCatacombsRegion.gd:500:North Tapestry — The Prior's Coffer", "kind": "dialogue", "region": "Louvain Catacombs (Book II)", "file": "scripts/regions/LouvainCatacombsRegion.gd", "line": 500, "speaker": "North Tapestry — The Prior's Coffer", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "\"Shun every corner stone. Along the third rank from the northern wall rests the Prior's Chalice—framed above by a Cross and below by a Crown, never beside a Stag.\""}, {"id": "LouvainCatacombsRegion.gd:513:%PLAYER%", "kind": "dialogue", "region": "Louvain Catacombs (Book II)", "file": "scripts/regions/LouvainCatacombsRegion.gd", "line": 513, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "desc"}, {"id": "LouvainCatacombsRegion.gd:518:Archivist Ledger Index (1431)", "kind": "dialogue", "region": "Louvain Catacombs (Book II)", "file": "scripts/regions/LouvainCatacombsRegion.gd", "line": 518, "speaker": "Archivist Ledger Index (1431)", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "\"CHRONOLOGICAL FILING KEY — Anno Domini 1431: Earlier Old Heverlee field inquiries sit NINE YEARS BACK (Anno 1422, West Vault); Conscripted Rig-Master warrants were sealed FIVE YEARS BACK (Anno 1426, East Vault).\""}, {"id": "LouvainCatacombsRegion.gd:527:Ledger — Anno 1422", "kind": "dialogue", "region": "Louvain Catacombs (Book II)", "file": "scripts/regions/LouvainCatacombsRegion.gd", "line": 527, "speaker": "Ledger — Anno 1422", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "\"Old Heverlee Shrine Key unrecovered; Louvain parish hunters neutralized by Inquisitor squad.\""}, {"id": "LouvainCatacombsRegion.gd:534:Chained Decree — Anno 1422 (9 Years Past)", "kind": "dialogue", "region": "Louvain Catacombs (Book II)", "file": "scripts/regions/LouvainCatacombsRegion.gd", "line": 534, "speaker": "Chained Decree — Anno 1422 (9 Years Past)", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "\"SECRET MEMORANDUM: Hunters of Louvain Parish intercepted at Old Heverlee Woods over the unrecovered Bronze Shrine Key. Official parish tally falsified as dragon casualties.\""}, {"id": "LouvainCatacombsRegion.gd:538:Warrant — Anno 1426", "kind": "dialogue", "region": "Louvain Catacombs (Book II)", "file": "scripts/regions/LouvainCatacombsRegion.gd", "line": 538, "speaker": "Warrant — Anno 1426", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "\"Rig-master Clara of Bruges moved east to Namur Quarry Rig-Works—bloodline traced to Old Heverlee.\""}, {"id": "LouvainCatacombsRegion.gd:545:Namur Requisition Warrant — Anno 1426 (5 Years Past)", "kind": "dialogue", "region": "Louvain Catacombs (Book II)", "file": "scripts/regions/LouvainCatacombsRegion.gd", "line": 545, "speaker": "Namur Requisition Warrant — Anno 1426 (5 Years Past)", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "\"HIGH PRIORITY: Abduct Bruges Ropewalk rig-master CLARA OF BRUGES to Namur Cliff-Citadel for heavy harness forging. Further archive cross-check links her to the Louvain Old Heverlee pair.\""}, {"id": "LouvainCatacombsRegion.gd:555:Parish Folio — Anno %s", "kind": "dialogue", "region": "Louvain Catacombs (Book II)", "file": "scripts/regions/LouvainCatacombsRegion.gd", "line": 555, "speaker": "Parish Folio — Anno %s", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "filler"}, {"id": "LouvainCatacombsRegion.gd:572:%DRAGON%", "kind": "dialogue", "region": "Louvain Catacombs (Book II)", "file": "scripts/regions/LouvainCatacombsRegion.gd", "line": 572, "speaker": "%DRAGON%", "portrait": "portrait_hatchling_stage1.png", "telepathic": true, "text": "Your hands are trembling... They buried the truth about your parents AND stole Clara east to Namur! Wait—heavy boots echoing across the Cloister stones above! Climb back out now!"}, {"id": "LouvainCityQuests.gd:19:Bell-Founder Pieter", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 19, "speaker": "Bell-Founder Pieter", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Listen to that bronze timbre ring cleanly across the Dijle! Carry those Resonance Chimes safely—ring one down an alley and Catchpoles chase echoes all day."}, {"id": "LouvainCityQuests.gd:22:Bell-Founder Pieter", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 22, "speaker": "Bell-Founder Pieter", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Aye—fine blue Dijle clay! Now lay a tight rope hitch onto the foundry gantry wheel beside the mould so I can draw the jacket true."}, {"id": "LouvainCityQuests.gd:24:Bell-Founder Pieter", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 24, "speaker": "Bell-Founder Pieter", "portrait": "portrait_uncle.png", "telepathic": false, "text": "The Church Catchpoles ordered six alarm-bells overnight and cracked my master mould! Dig wet clay down by the Dijle river bank and haul my gantry pulley taut if you want proper bronze Resonance Chimes."}, {"id": "LouvainCityQuests.gd:31:Bell-Founder Pieter", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 31, "speaker": "Bell-Founder Pieter", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Hold up lad—pack wet alluvial clay from the Dijle River Slip first before hoisting the casing!"}, {"id": "LouvainCityQuests.gd:41:Bell-Founder Pieter", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 41, "speaker": "Bell-Founder Pieter", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Seated tight as Flemish oak! Take two tuned Bronze Resonance Chimes—and slip into your hood whenever Catchpoles pace the bridge."}, {"id": "LouvainCityQuests.gd:50:Guildmistress Aleidis", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 50, "speaker": "Guildmistress Aleidis", "portrait": "portrait_clara.png", "telepathic": false, "text": "Bless me—you have your mother's eyes, %s! Years back after your parents rode out to Old Heverlee, they marched straight into this tavern and burned their Church hunting seals in the hearth."}, {"id": "LouvainCityQuests.gd:51:Guildmistress Aleidis", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 51, "speaker": "Guildmistress Aleidis", "portrait": "portrait_clara.png", "telepathic": false, "text": "Swore someone above St. Donatian's altar was excavating something older than Flanders. Two nights later, men in black tabards seized every deed from the Abbey Scriptorium northeast across the bridge."}, {"id": "LouvainCityQuests.gd:57:Veteran Martijn", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 57, "speaker": "Veteran Martijn", "portrait": "portrait_watchman.png", "telepathic": false, "text": "The High Inquisitor never told the parish a dragon killed your folks—he paid crossbowmen to ambush us by an ancient gold-carved stone vault in Old Heverlee."}, {"id": "LouvainCityQuests.gd:65:Veteran Martijn", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 65, "speaker": "Veteran Martijn", "portrait": "portrait_watchman.png", "telepathic": false, "text": "My old Oak-and-Hound signet! You pulled it back from those Abbey thieves..."}, {"id": "LouvainCityQuests.gd:66:Veteran Martijn", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 66, "speaker": "Veteran Martijn", "portrait": "portrait_watchman.png", "telepathic": false, "text": "Hear the truth then, boy: no beast slaughtered your mother and father at Old Heverlee. Church Inquisitors rode down our camp when your father refused to hand over a bronze shrine key they dug out beneath the oaks!"}, {"id": "LouvainCityQuests.gd:69:Veteran Martijn", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 69, "speaker": "Veteran Martijn", "portrait": "portrait_watchman.png", "telepathic": false, "text": "Leave an old one-eyed hunter to his ale, lad... unless you pry my Oak-and-Hound signet ring back from the watch chest Catchpoles locked away east behind Tiensestraat."}, {"id": "LouvainCityQuests.gd:74:Sister Katelijne", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 74, "speaker": "Sister Katelijne", "portrait": "portrait_maren.png", "telepathic": false, "text": "Keep those Smoke-Pellets beside your belt—cast one under foot if Catchpole crossbows lock the square, and search the garrison watch-crate east down Tiensestraat for confiscated guild trinkets."}, {"id": "LouvainCityQuests.gd:76:Sister Katelijne", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 76, "speaker": "Sister Katelijne", "portrait": "portrait_maren.png", "telepathic": false, "text": "Rust wedged my dye-vat sluice shut while Catchpoles camp at the gate! Snap the jammed lever free with a strong rope or warm ember and I'll pack fresh Smoke-Pellets for you."}, {"id": "LouvainCityQuests.gd:88:Sister Katelijne", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 88, "speaker": "Sister Katelijne", "portrait": "portrait_maren.png", "telepathic": false, "text": "Clean water at last! Here—two ash-and-wax Smoke-Pellets. Oh, and Catchpoles dumped an old hunter's brass signet inside the garrison watch-chest east up Tiensestraat."}, {"id": "LouvainCityQuests.gd:103:Master Mason Matthijs", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 103, "speaker": "Master Mason Matthijs", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Look up at that pale limestone spire crowning Sint-Pieterskerk! Brussels' stewards can crane their necks all winter—Louvain touches the clouds first!"}, {"id": "LouvainCityQuests.gd:110:Master Mason Matthijs", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 110, "speaker": "Master Mason Matthijs", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Brussels brags their belfry spire will scrape the clouds first! My quarry barge docked over at Vismarkt Harbor Quay loaded with white Gobertange ashlar stone, then Catchpoles hauled the carter off."}, {"id": "LouvainCityQuests.gd:111:Master Mason Matthijs", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 111, "speaker": "Master Mason Matthijs", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Unlash that ashlar stone crate on Vismarkt Quay and man the timber hoist crane right beside me—we'll stack the highest spire in Brabant!"}, {"id": "LouvainCityQuests.gd:124:%DRAGON%", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 124, "speaker": "%DRAGON%", "portrait": "portrait_hatchling_stage1.png", "telepathic": true, "text": "Pale quarry limestone in our satchel—Matthijs's hoist crane by Sint-Pieterskerk is ready when we are."}, {"id": "LouvainCityQuests.gd:132:Master Mason Matthijs", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 132, "speaker": "Master Mason Matthijs", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Nothing left to sling yet, apprentice! Fetch our lashed Gobertange Ashlar Crate down on Vismarkt Stone Quay west across the bridge first."}, {"id": "LouvainCityQuests.gd:152:Master Mason Matthijs", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 152, "speaker": "Master Mason Matthijs", "portrait": "portrait_uncle.png", "telepathic": false, "text": "By St. Peter's keys—every limestone course plumb and a slate spire piercing high above Brussels!"}, {"id": "LouvainCityQuests.gd:153:Master Mason Matthijs", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 153, "speaker": "Master Mason Matthijs", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Take my Guild Plumb-Signet, hot quarry rations for your belly, and an ash flask my apprentice found behind the cloister wall!"}, {"id": "LouvainCityQuests.gd:159:Beadle Hendrik", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 159, "speaker": "Beadle Hendrik", "portrait": "portrait_watchman.png", "telepathic": false, "text": "Ha! Two Brussels aldermen nearly choked on their abbey ale peering up at Sint-Pieterskerk's new limestone spire—Matthijs sends his regards!"}, {"id": "LouvainCityQuests.gd:161:Beadle Hendrik", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityQuests.gd", "line": 161, "speaker": "Beadle Hendrik", "portrait": "portrait_watchman.png", "telepathic": false, "text": "Mind the cobbles beneath De Lakenhalle's arches, lad—the Duke's new 1425 University masters lodge upstairs above the Cloth Hall looms, and Catchpoles have been questioning every clerk carrying Latin ink."}, {"id": "LouvainCityRegion.gd:275:Catchpole Sergeant", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityRegion.gd", "line": 275, "speaker": "Catchpole Sergeant", "portrait": "portrait_watchman.png", "telepathic": false, "text": "Seal the Abbey steps! That apprentice just lifted the Old Heverlee writs—catch that wyrmling alive for twenty florins!"}, {"id": "LouvainCityRegion.gd:502:%DRAGON%", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityRegion.gd", "line": 502, "speaker": "%DRAGON%", "portrait": "portrait_hatchling_stage1.png", "telepathic": true, "text": "The road south is jarred wide open. Iron chains tremble when our fire sings through them—Old Heverlee awaits beyond the wall."}, {"id": "LouvainCityRegion.gd:574:South Post Sign", "kind": "dialogue", "region": "City of Louvain (Book II)", "file": "scripts/regions/LouvainCityRegion.gd", "line": 574, "speaker": "South Post Sign", "portrait": "portrait_baker.png", "telepathic": false, "text": "\"OLD HEVERLEE WOODS & ABBEY FOREST TRAIL — 3 LEAGUES SOUTH.\""}, {"id": "OldHeverleeRegion.gd:268:%PLAYER%", "kind": "dialogue", "region": "Old Heverlee Woods (Book II)", "file": "scripts/regions/OldHeverleeRegion.gd", "line": 268, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Father's yew stave snapped in half... and crimson-fletched Inquisitor bolts buried deep inside the oak heartwood."}, {"id": "OldHeverleeRegion.gd:269:%DRAGON%", "kind": "dialogue", "region": "Old Heverlee Woods (Book II)", "file": "scripts/regions/OldHeverleeRegion.gd", "line": 269, "speaker": "%DRAGON%", "portrait": "portrait_hatchling_stage1.png", "telepathic": true, "text": "Old bronze hums south across the creek below thick brambles. Your folk buried something fierce down there."}, {"id": "OldHeverleeRegion.gd:280:Inquisitor Field Dispatch", "kind": "dialogue", "region": "Old Heverlee Woods (Book II)", "file": "scripts/regions/OldHeverleeRegion.gd", "line": 280, "speaker": "Inquisitor Field Dispatch", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "\"SWEEP ZOET WATER SOUTH BANK FOR SUNKEN SHRINE ENTRANCE. BARGE CONVOY SHIPS CAPTURED DRAKES TO NAMUR UPON BELL SIGNAL.\""}, {"id": "OldHeverleeRegion.gd:302:%PLAYER%", "kind": "dialogue", "region": "Old Heverlee Woods (Book II)", "file": "scripts/regions/OldHeverleeRegion.gd", "line": 302, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Fly fast east to Anna, girl—tell her the Church bleeds live dragons at Namur, and they seized Clara five years back."}, {"id": "OldHeverleeRegion.gd:303:%DRAGON%", "kind": "dialogue", "region": "Old Heverlee Woods (Book II)", "file": "scripts/regions/OldHeverleeRegion.gd", "line": 303, "speaker": "%DRAGON%", "portrait": "portrait_hatchling_stage1.png", "telepathic": true, "text": "Grey wings climb above the beech ridge... Now let's see what Aunt Anna answers on the river winds."}, {"id": "OldHeverleeShrineRegion.gd:247:%DRAGON%", "kind": "dialogue", "region": "Old Heverlee Woods (Book II)", "file": "scripts/regions/OldHeverleeShrineRegion.gd", "line": 247, "speaker": "%DRAGON%", "portrait": "portrait_hatchling_stage1.png", "telepathic": true, "text": "Look at that horned shadow above the chained dragons... crimson veins pouring into an iron vessel. That's why Church inquisitors harvest hearts alive."}, {"id": "OldHeverleeShrineRegion.gd:248:%PLAYER%", "kind": "dialogue", "region": "Old Heverlee Woods (Book II)", "file": "scripts/regions/OldHeverleeShrineRegion.gd", "line": 248, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "A Devildragon ritual... Mother and Father sealed the key inside this vault so nobody could awaken it."}, {"id": "OldHeverleeShrineRegion.gd:264:%PLAYER%", "kind": "dialogue", "region": "Old Heverlee Woods (Book II)", "file": "scripts/regions/OldHeverleeShrineRegion.gd", "line": 264, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "The Old Heverlee Shrine Key... still warm beneath the dust! And look—eastern stairs opened beyond the plinth!"}, {"id": "OldHeverleeShrineRegion.gd:265:%DRAGON%", "kind": "dialogue", "region": "Old Heverlee Woods (Book II)", "file": "scripts/regions/OldHeverleeShrineRegion.gd", "line": 265, "speaker": "%DRAGON%", "portrait": "portrait_hatchling_stage1.png", "telepathic": true, "text": "Our bond just rang like sun-struck gold! Follow that breeze east—Kestrel will find us on the ridge above."}, {"id": "PortOfBrugesAmbush.gd:150:Hooded Brotherhood Rider", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesAmbush.gd", "line": 150, "speaker": "Hooded Brotherhood Rider", "portrait": "portrait_brotherhood.png", "telepathic": false, "text": "Hold it, boy. Turn around and walk away from the square."}, {"id": "PortOfBrugesAmbush.gd:151:%PLAYER%", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesAmbush.gd", "line": 151, "speaker": "%PLAYER%", "portrait": "portrait_boy_angry.png", "telepathic": false, "text": "Let go of me! You took Clara—I found your strap! GUARDS!!"}, {"id": "PortOfBrugesAmbush.gd:152:Hooded Brotherhood Rider", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesAmbush.gd", "line": 152, "speaker": "Hooded Brotherhood Rider", "portrait": "portrait_brotherhood.png", "telepathic": false, "text": "Shut his mouth! Look what's in his fist—finish it before the watch turns."}, {"id": "PortOfBrugesAmbush.gd:165:Anna", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesAmbush.gd", "line": 165, "speaker": "Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Put the blade away."}, {"id": "PortOfBrugesAmbush.gd:166:Hooded Brotherhood Rider", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesAmbush.gd", "line": 166, "speaker": "Hooded Brotherhood Rider", "portrait": "portrait_brotherhood.png", "telepathic": false, "text": "Captain Anna—he's fifty paces from the pulpit!"}, {"id": "PortOfBrugesAmbush.gd:167:Anna", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesAmbush.gd", "line": 167, "speaker": "Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "I'm not slitting a twelve-year-old's throat over a scrap of leather. Blindfold him and clip him into Virelai's belly-net."}, {"id": "PortOfBrugesAmbush.gd:230:Gatewarden Maerten", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesAmbush.gd", "line": 230, "speaker": "Gatewarden Maerten", "portrait": "portrait_watchman.png", "telepathic": false, "text": "msg"}, {"id": "PortOfBrugesAmbush.gd:237:Customsman Dirk", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesAmbush.gd", "line": 237, "speaker": "Customsman Dirk", "portrait": "portrait_watchman.png", "telepathic": false, "text": "msg_e"}, {"id": "PortOfBrugesRegion.gd:216:Shipmaster Hendrik", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 216, "speaker": "Shipmaster Hendrik", "portrait": "portrait_shipmaster.png", "telepathic": false, "text": "Way enough! Tie the bow line at the forward cleat so I can drop the plank, then heave that salt-herring crate up to Vos."}, {"id": "PortOfBrugesRegion.gd:347:Shipmaster Hendrik", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 347, "speaker": "Shipmaster Hendrik", "portrait": "portrait_shipmaster.png", "telepathic": false, "text": "Way enough! Tie the bow line at the forward cleat so I can drop the plank, then heave that salt-herring crate up to Vos."}, {"id": "PortOfBrugesRegion.gd:490:Shipmaster Hendrik", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 490, "speaker": "Shipmaster Hendrik", "portrait": "portrait_shipmaster.png", "telepathic": false, "text": "Clean Clove Hitch, lad. Plank's down. Grab that salt-herring crate off the deck before you run off to your sister."}, {"id": "PortOfBrugesRegion.gd:506:Shipmaster Hendrik", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 506, "speaker": "Shipmaster Hendrik", "portrait": "portrait_shipmaster.png", "telepathic": false, "text": "Almost at the quay, %s. Stand ready by the bow cleat."}, {"id": "PortOfBrugesRegion.gd:508:Shipmaster Hendrik", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 508, "speaker": "Shipmaster Hendrik", "portrait": "portrait_shipmaster.png", "telepathic": false, "text": "Tie the bow line to that forward cleat with a Clove Hitch so the crew can lower the gangplank."}, {"id": "PortOfBrugesRegion.gd:510:Shipmaster Hendrik", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 510, "speaker": "Shipmaster Hendrik", "portrait": "portrait_shipmaster.png", "telepathic": false, "text": "Quartermaster Vos is waiting by the Warehouse north of the wharf. Tell Clara I said good evening."}, {"id": "PortOfBrugesRegion.gd:512:Shipmaster Hendrik", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 512, "speaker": "Shipmaster Hendrik", "portrait": "portrait_shipmaster.png", "telepathic": false, "text": "Good work today, %s. Keep that rigging knife dry—same tide tomorrow at dawn."}, {"id": "PortOfBrugesRegion.gd:522:Quartermaster Vos", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 522, "speaker": "Quartermaster Vos", "portrait": "portrait_quartermaster.png", "telepathic": false, "text": "Ah, %s—set the herring crate inside the bay. Here's three copper groats for your hauling."}, {"id": "PortOfBrugesRegion.gd:529:Quartermaster Vos", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 529, "speaker": "Quartermaster Vos", "portrait": "portrait_quartermaster.png", "telepathic": false, "text": "Wait—dry hemp wrapped inside that tide-drift crate? Good weight to it. Trade you an old pocket compass I've no use for; needle still holds true north."}, {"id": "PortOfBrugesRegion.gd:531:%PLAYER%", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 531, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Obliged, Master Vos."}, {"id": "PortOfBrugesRegion.gd:541:Quartermaster Vos", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 541, "speaker": "Quartermaster Vos", "portrait": "portrait_quartermaster.png", "telepathic": false, "text": "Dry hemp salvaged from the Zwin? Good haul, %s—take this spare pocket compass in exchange. Needle still holds true north."}, {"id": "PortOfBrugesRegion.gd:544:Quartermaster Vos", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 544, "speaker": "Quartermaster Vos", "portrait": "portrait_quartermaster.png", "telepathic": false, "text": "Warehouse is tallied for the night. Safe walk home to Willem's, boy."}, {"id": "PortOfBrugesRegion.gd:546:Quartermaster Vos", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 546, "speaker": "Quartermaster Vos", "portrait": "portrait_quartermaster.png", "telepathic": false, "text": "Still waiting on that last salt-herring crate from De Zwaan's deck, lad."}, {"id": "PortOfBrugesRegion.gd:553:Harbor Decree", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 553, "speaker": "Harbor Decree", "portrait": "portrait_watchman.png", "telepathic": false, "text": "'BY ORDER OF THE HOLY INQUISITION: Five silver groats for a slain wyrm-hide; TWENTY gold florins for any dragon delivered ALIVE in iron chains! Severe penalties for Ropewalk spinners supplying greased hemp to outlawed riders.'"}, {"id": "PortOfBrugesRegion.gd:554:Faded Brabant Notice", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 554, "speaker": "Faded Brabant Notice", "portrait": "portrait_watchman.png", "telepathic": false, "text": "'Missing near Old Heverlee, four winters past — two Hunter Guilders of Louvain.'"}, {"id": "PortOfBrugesRegion.gd:561:Dockhand Jan", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 561, "speaker": "Dockhand Jan", "portrait": "portrait_quartermaster.png", "telepathic": false, "text": "Watch your boot-strings along the canal edge, %s! Current sucked a whole coil of Clara's brass shuttles off the north piling earlier today."}, {"id": "PortOfBrugesRegion.gd:562:Dockhand Jan", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 562, "speaker": "Dockhand Jan", "portrait": "portrait_quartermaster.png", "telepathic": false, "text": "And keep limber near the cranes—tuck your shoulder into a quick roll under any swinging yardarm before it knocks you in the Zwin. Quick tumbling gets you clear of harbor patrols too!"}, {"id": "PortOfBrugesRegion.gd:568:Dockhand Piet", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 568, "speaker": "Dockhand Piet", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Seen iron-helmeted Church Watchmen unloading fresh ballista bolts down on the east pier, lad. Something's flying inland past the dunes at night."}, {"id": "PortOfBrugesRegion.gd:599:%PLAYER%", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 599, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Here—fished this out of the eddy by the north pilings. Yours?"}, {"id": "PortOfBrugesRegion.gd:600:Clara", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 600, "speaker": "Clara", "portrait": "portrait_clara.png", "telepathic": false, "text": "My oilskin pouch! Thought the Zwin tide took it clear past the sea-gate. Look—Mother's Louvain brass thimble was still wrapped inside."}, {"id": "PortOfBrugesRegion.gd:601:Clara", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 601, "speaker": "Clara", "portrait": "portrait_clara.png", "telepathic": false, "text": "Keep it, %s. You pulled it back. Take this cake of our beeswax too—rub it into your hemp so the salt doesn't rot it."}, {"id": "PortOfBrugesRegion.gd:609:Clara", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 609, "speaker": "Clara", "portrait": "portrait_clara.png", "telepathic": false, "text": "There you are, %s. Smell like low tide again."}, {"id": "PortOfBrugesRegion.gd:610:Clara", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 610, "speaker": "Clara", "portrait": "portrait_clara.png", "telepathic": false, "text": "Church-hired wagon-wrights came sniffing round the Ropewalk at noon asking who braids our gale-tension hemp, so I kept my head down and rigged a three-prong brass hook for you instead. Show me your Bruges Whipping-Knot."}, {"id": "PortOfBrugesRegion.gd:615:Clara", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 615, "speaker": "Clara", "portrait": "portrait_clara.png", "telepathic": false, "text": "Not bad, little brother—weighted like that, you could haul drifted timber straight out of the canal. Oh, Uncle Willem's out of bread. Stop by Pieter's stall in the square on your way home, yeah?"}, {"id": "PortOfBrugesRegion.gd:626:Clara", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 626, "speaker": "Clara", "portrait": "portrait_clara.png", "telepathic": false, "text": "Grab that rye loaf before Pieter shuts his stall. I'll meet you back at Uncle Willem's once I bank the hemp fires."}, {"id": "PortOfBrugesRegion.gd:644:Church Inquisitor", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 644, "speaker": "Church Inquisitor", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "Hear the decree of the Holy See! Every wyrm is a plague upon field and flock! Honor the Dragon Hunters who bleed to keep Flanders clear!"}, {"id": "PortOfBrugesRegion.gd:645:Church Inquisitor", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 645, "speaker": "Church Inquisitor", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "And keep watch over your neighbors—rumors speak of traitors in the borderlands, riders in leather harness who shelter the beasts in secret! Any soul who turns them in earns the magistrate's silver!"}, {"id": "PortOfBrugesRegion.gd:654:Baker Pieter", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 654, "speaker": "Baker Pieter", "portrait": "portrait_baker.png", "telepathic": false, "text": "Run along home, %s—don't let that rye loaf go cold!"}, {"id": "PortOfBrugesRegion.gd:661:Baker Pieter", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 661, "speaker": "Baker Pieter", "portrait": "portrait_baker.png", "telepathic": false, "text": "One crusty rye loaf for Willem's table—that'll be one copper, lad."}, {"id": "PortOfBrugesRegion.gd:662:%PLAYER%", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 662, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Thanks, Master Pieter."}, {"id": "PortOfBrugesRegion.gd:665:Church Inquisitor", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 665, "speaker": "Church Inquisitor", "portrait": "portrait_inquisitor.png", "telepathic": false, "text": "Hear the decree! Honor the Dragon Hunters—and report any secret riders in leather harness to the magistrate!"}, {"id": "PortOfBrugesRegion.gd:666:%PLAYER%", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 666, "speaker": "%PLAYER%", "portrait": "portrait_boy_angry.png", "telepathic": false, "text": "Good. Hang the riders with them."}, {"id": "PortOfBrugesRegion.gd:688:Harbor Gatehouse Post", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 688, "speaker": "Harbor Gatehouse Post", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "NORTH: Steenstraat & Walled City of Bruges  |  EAST PAST ROPEWALK: Coastal Outskirts Towpath"}, {"id": "PortOfBrugesRegion.gd:700:Towpath Milestone", "kind": "dialogue", "region": "Port of Bruges (Ch. 1)", "file": "scripts/regions/PortOfBrugesRegion.gd", "line": 700, "speaker": "Towpath Milestone", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "NORTH: Coastal Outskirts, Zwin Bridge & Sanctuary Dunes  |  WEST: Harbour Quay & City Gate"}, {"id": "SanctuaryAct4.gd:188:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 188, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Merciful heavens... look at that shell in your arms. Obsidian black threaded with gold veins—no Bestiary in our chests records a breed like that! Hand it over to me right now, %s."}, {"id": "SanctuaryAct4.gd:189:Bellman Matthijs", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 189, "speaker": "Bellman Matthijs", "portrait": "portrait_matthijs.png", "telepathic": false, "text": "Hendrick's right. The senior Brotherhood Council elders will want that egg taken into custody tonight—crated under iron lock and hidden beneath Ghent before rumor slips out."}, {"id": "SanctuaryAct4.gd:190:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 190, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Get back—nobody is taking my egg! Its mother tore her wing open shielding it in that burning hollow, and I carried it through freezing sleet to keep it warm! Seal it in a cold Ghent vault and it'll die!"}, {"id": "SanctuaryAct4.gd:191:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 191, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "And keep it clinging to a seventeen-year-old's hip?! If word of an unknown black egg reaches Church ears, every bolt-cart in Flanders will climb this ridge before frost! Give the egg up, lad!"}, {"id": "SanctuaryAct4.gd:192:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 192, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "I won't hand it over to anyone—it stays with me!"}, {"id": "SanctuaryAct4.gd:193:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 193, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Quiet down, both of you! Step back from %s's coat, Hendrick—"}, {"id": "SanctuaryAct4.gd:212:Outpost Scout", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 212, "speaker": "Outpost Scout", "portrait": "portrait_watchman.png", "telepathic": false, "text": "Captain Anna! Urgent word off the western canal road—the Church is setting up for a huge action inside the Walled City of Bruges! Armed Catchpoles, Inquisitors, and search teams are pouring through the city gates right now!"}, {"id": "SanctuaryAct4.gd:213:Bellman Matthijs", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 213, "speaker": "Bellman Matthijs", "portrait": "portrait_matthijs.png", "telepathic": false, "text": "A full Church muster inside Bruges's walls?! They're stopping every barge and cart at the gates—what stirred the Bishop's hounds into such a frenzy?"}, {"id": "SanctuaryAct4.gd:214:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 214, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Then the Council debate waits until we know what they're searching for! Settle down, Hendrick—nobody takes %s's egg tonight."}, {"id": "SanctuaryAct4.gd:215:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 215, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Set the black egg on the warm brazier cradle beside Virelai right here—Sister Maren and I will guard its heat personally. %s, you know Bruges's alleys and canal bridges better than any border rider. Take the West Cliff Trail into the Walled City and find out what the Church's big action is all about!"}, {"id": "SanctuaryAct4.gd:216:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 216, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Keep the coals glowing beneath it, Anna—don't let Hendrick near that cradle. I'll sneak into the Walled City of Bruges and uncover what they're planning."}, {"id": "SanctuaryAct4.gd:250:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 250, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "You're back past curfew—look half-winded. What were the Catchpoles hauling across Bruges square?"}, {"id": "SanctuaryAct4.gd:251:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 251, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "...Nothing out of the ordinary. Only Church tithe iron and noise at the Cloth Hall to frighten the weavers."}, {"id": "SanctuaryAct4.gd:252:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 252, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Hmph. All the same, the senior Council arrives at first bell. Keep Night-Watch double-lit around the egg brazier till dawn, boys."}, {"id": "SanctuaryAct4.gd:433:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryAct4.gd", "line": 433, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "No time to wander back into town—come tell me what the Church is doing beside Virelai."}, {"id": "SanctuaryArrivalCutscene.gd:123:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryArrivalCutscene.gd", "line": 123, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Keep your boots clear of the cliff drop, boy."}, {"id": "SanctuaryArrivalCutscene.gd:124:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryArrivalCutscene.gd", "line": 124, "speaker": "%PLAYER%", "portrait": "portrait_boy_angry.png", "telepathic": false, "text": "Keep that thing back! What did you do with my sister?!"}, {"id": "SanctuaryArrivalCutscene.gd:125:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryArrivalCutscene.gd", "line": 125, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "We don't snatch ropewalk girls in the dark. Half the Church's scouts fly stolen dragon-gear when they raid the harbor."}, {"id": "SanctuaryArrivalCutscene.gd:126:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryArrivalCutscene.gd", "line": 126, "speaker": "%PLAYER%", "portrait": "portrait_boy_angry.png", "telepathic": false, "text": "Liar! Then why knock me out on the cobbles?!"}, {"id": "SanctuaryArrivalCutscene.gd:127:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryArrivalCutscene.gd", "line": 127, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Because three steps more would have brought an Inquisitor's torch down on everyone here. You want bread and answers? Start under Saddler Hendrick by the south rack."}, {"id": "SanctuaryMontageCutscene.gd:358:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryMontageCutscene.gd", "line": 358, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Fourteen fits you better than those Bruges rags did. Matthijs is squinting at the east wind-mast, Bram's sorting pasture mutton, and Virelai's restless for Coast Patrol."}, {"id": "SanctuaryNarrative.gd:16:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 16, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Pull the blindfold off him. Watch your boots along the drop, boy."}, {"id": "SanctuaryNarrative.gd:21:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 21, "speaker": "%PLAYER%", "portrait": "portrait_boy_angry.png", "telepathic": false, "text": "Keep that thing back! What did you do with my sister?!"}, {"id": "SanctuaryNarrative.gd:22:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 22, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "We don't abduct ropewalk girls. Church-backed slavers strip salvaged wyrm-hide straps off shot wild dragons to truss prisoners—and force Bruges's finest cordage weavers to braid heavy suppression harnesses inland."}, {"id": "SanctuaryNarrative.gd:23:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 23, "speaker": "%PLAYER%", "portrait": "portrait_boy_angry.png", "telepathic": false, "text": "Liar! Then why knock me out on the cobbles?!"}, {"id": "SanctuaryNarrative.gd:24:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 24, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Because three steps more would have brought an Inquisitor's torch down on everyone here. You want bread and answers? Start under Saddler Hendrick by the south rack."}, {"id": "SanctuaryNarrative.gd:39:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 39, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Set it across the trestle. Not bad—you carry heavy cordage like a real river-lad, not a soft clerk."}, {"id": "SanctuaryNarrative.gd:40:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 40, "speaker": "%PLAYER%", "portrait": "portrait_boy_angry.png", "telepathic": false, "text": "Why soften dragon-leather with tallow if these beasts tear steel chains apart?"}, {"id": "SanctuaryNarrative.gd:41:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 41, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Raw straps saw straight into wing-sinew in wet weather. Keep a harness supple and she spares her skin; rush it and a rider drops three leagues. Take a look at Virelai's starboard shoulder-ring."}, {"id": "SanctuaryNarrative.gd:45:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 45, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "So Anna dragged a Louvain-born dockrat out of the Zwin mist. Wipe that scowl off—while you stand on this cliff, you work for your porridge."}, {"id": "SanctuaryNarrative.gd:46:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 46, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "My curing bench's running bare—there's salted wyrm-hide rolled down by the south store-crates if your back works better than your mouth."}, {"id": "SanctuaryNarrative.gd:50:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 50, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Hide's soaking well. See if Virelai holds still long enough for you to mend that frayed bronze shoulder-ring."}, {"id": "SanctuaryNarrative.gd:54:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 54, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Huh. Steady thumb-twist—better than half my greenhorns last spring. Sister Maren looked short-handed up by the northern cauldron."}, {"id": "SanctuaryNarrative.gd:61:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 61, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Two winters on and you've put an inch on your wrists, %s. Good fit in that tan apprentice leather—not a Bruges dockrat anymore."}, {"id": "SanctuaryNarrative.gd:62:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 62, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Never let a wet salt-knot freeze under a buckle. Old habit."}, {"id": "SanctuaryNarrative.gd:63:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 63, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Keep it. Test your speed on that oak Drill Board beside my rack whenever you've a spare minute—clear the sand-glass cleanly and my Topman's Timing Ring is yours."}, {"id": "SanctuaryNarrative.gd:68:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 68, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Bellman Matthijs went over the east gorge testing wind-pennants, and Kestrel's squawking for scrap fish by the fire. Virelai also keeps glancing at her left wing-hinge."}, {"id": "SanctuaryNarrative.gd:72:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 72, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Don't glare at me like I stole your purse, %s. An unknown black egg brings Church Catchpoles straight to our cliffs—as soon as you bring word back from Bruges, the elders decide where it's locked away."}, {"id": "SanctuaryNarrative.gd:76:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 76, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Five winters since I dropped a splicing needle in your fist, lad. Look at you in that oiled coat—broad enough across the ribs for a senior chest-band."}, {"id": "SanctuaryNarrative.gd:77:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 77, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Wait till this gale clears, Hendrick. If scouts find any word out of Louvain or east of Bruges—"}, {"id": "SanctuaryNarrative.gd:78:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 78, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "We haven't forgotten your sister, %s. Bring Anna and Virelai back whole through the thunderheads first."}, {"id": "SanctuaryNarrative.gd:93:Sister Maren", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 93, "speaker": "Sister Maren", "portrait": "portrait_maren.png", "telepathic": false, "text": "Steady pour—mind the steam. Cliffsage, crushed yarrow, and wild honey soften scorched hide faster than mutton grease."}, {"id": "SanctuaryNarrative.gd:94:Sister Maren", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 94, "speaker": "Sister Maren", "portrait": "portrait_maren.png", "telepathic": false, "text": "Keep the jar tucked near your chest so it stays warm—and gentle hands around a cornered dragon, alright?"}, {"id": "SanctuaryNarrative.gd:98:Sister Maren", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 98, "speaker": "Sister Maren", "portrait": "portrait_maren.png", "telepathic": false, "text": "Easy, little shiphand—don't hover so stiff near the fire. Scouts rescued a young Greyling from a Church hunter wagon last night, still bleeding and bound in bolted iron wing-cuffs."}, {"id": "SanctuaryNarrative.gd:99:Sister Maren", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 99, "speaker": "Sister Maren", "portrait": "portrait_maren.png", "telepathic": false, "text": "Can't steep cliffsage in an empty kettle—and my back won't haul a cold bucket up from the east spring today."}, {"id": "SanctuaryNarrative.gd:103:Sister Maren", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 103, "speaker": "Sister Maren", "portrait": "portrait_maren.png", "telepathic": false, "text": "The jar's still warm—hurry back across the east chasm. Once those forged hunter shackles break loose, she'll need that salve fast."}, {"id": "SanctuaryNarrative.gd:107:Sister Maren", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 107, "speaker": "Sister Maren", "portrait": "portrait_maren.png", "telepathic": false, "text": "Did you see how quietly she tucked her snout against your sleeve once the stinging stopped? Even fear knows kindness when it smells warm herbs."}, {"id": "SanctuaryNarrative.gd:111:Sister Maren", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 111, "speaker": "Sister Maren", "portrait": "portrait_maren.png", "telepathic": false, "text": "Still drying bundles before frost, %s. Kestrel's wings healed clean last summer—you can visit her uncovered on the sunny east shelf."}, {"id": "SanctuaryNarrative.gd:115:Sister Maren", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 115, "speaker": "Sister Maren", "portrait": "portrait_maren.png", "telepathic": false, "text": "Rest easy, %s—I'm keeping fresh beech-coals stoked under that brazier stand myself. Hendrick won't lay a finger on your black egg while you're scouting inside Bruges."}, {"id": "SanctuaryNarrative.gd:119:Sister Maren", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 119, "speaker": "Sister Maren", "portrait": "portrait_maren.png", "telepathic": false, "text": "Seventeen already, and tall enough to duck under the drying beam. Pack two linen rolls beneath your jerkin—storm winds carry cold sleet up high."}, {"id": "SanctuaryNarrative.gd:127:Bellman Matthijs", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 127, "speaker": "Bellman Matthijs", "portrait": "portrait_matthijs.png", "telepathic": false, "text": "Hah—you took that chasm post one-handed like you've lived on ropes your whole life! Almost forgot you used to white-knuckle the plank bridge back at twelve."}, {"id": "SanctuaryNarrative.gd:128:Bellman Matthijs", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 128, "speaker": "Bellman Matthijs", "portrait": "portrait_matthijs.png", "telepathic": false, "text": "Before you muster up for Coast Patrol, help me heave the east gale-pennant taut on that signal mast beside the drop. Tie a clean Bowline so we read wind-shear cleanly."}, {"id": "SanctuaryNarrative.gd:132:Bellman Matthijs", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 132, "speaker": "Bellman Matthijs", "portrait": "portrait_matthijs.png", "telepathic": false, "text": "Pennant's snapping crisp east-by-northeast! Head back west and check Virelai's wing-hinge before Anna blows takeoff."}, {"id": "SanctuaryNarrative.gd:136:Bellman Matthijs", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 136, "speaker": "Bellman Matthijs", "portrait": "portrait_matthijs.png", "telepathic": false, "text": "Half the camp's still shouting over that black-and-gold egg—half say take it off you and vault it at Ghent, half swear it belongs beside you. Go down the West Trail into Bruges and learn what the Church is mustering before first light!"}, {"id": "SanctuaryNarrative.gd:147:Bellman Matthijs", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 147, "speaker": "Bellman Matthijs", "portrait": "portrait_matthijs.png", "telepathic": false, "text": "Catch—still smells of oak bark and beeswax. Hendrick stitched those extra brass D-rings under the arms for your seventeen-year-old reach."}, {"id": "SanctuaryNarrative.gd:148:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 148, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Fits clean across the shoulders... Beats my patched tan apprentice leather by ten miles."}, {"id": "SanctuaryNarrative.gd:149:Bellman Matthijs", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 149, "speaker": "Bellman Matthijs", "portrait": "portrait_matthijs.png", "telepathic": false, "text": "Well, retire it at last, senior harness-man. Anna and Virelai are waiting at the cliff perch for the Eastern Ridge Storm Recon."}, {"id": "SanctuaryNarrative.gd:153:Bellman Matthijs", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 153, "speaker": "Bellman Matthijs", "portrait": "portrait_matthijs.png", "telepathic": false, "text": "Keep both waist-carabiners clipped in the thunderheads, %s. We'll light the cliff beacons till Virelai banks home."}, {"id": "SanctuaryNarrative.gd:162:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 162, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Hold steady, girl—just scrubbing winter sea-salt out from under your wing-fold before the patrol."}, {"id": "SanctuaryNarrative.gd:172:Virelai", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 172, "speaker": "Virelai", "portrait": "portrait_virelai.png", "telepathic": false, "text": "Your hands are steadier than they were two snowfalls ago, young mariner. And colder water burns less than vinegar."}, {"id": "SanctuaryNarrative.gd:173:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 173, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "You usually stay silent around the trestle... Can I ask you something straight, Virelai?"}, {"id": "SanctuaryNarrative.gd:174:Virelai", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 174, "speaker": "Virelai", "portrait": "portrait_virelai.png", "telepathic": false, "text": "You wish to ask about Old Heverlee. Anna never hid the Louvain reports about your parents."}, {"id": "SanctuaryNarrative.gd:175:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 175, "speaker": "%PLAYER%", "portrait": "portrait_boy_angry.png", "telepathic": false, "text": "Four hunters went into the woods with hemp and torches, and none came home. Why should I trust any wyrm not to kill the moment she breaks chain?!"}, {"id": "SanctuaryNarrative.gd:176:Virelai", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 176, "speaker": "Virelai", "portrait": "portrait_virelai.png", "telepathic": false, "text": "Because chains bring harpoons, fire, and crying eggs crushed in stone pits. Yet hear me carefully: I flew low above Old Heverlee two winters later, and no dragon's scorching breath scarred those beech trees—only broken hunter iron."}, {"id": "SanctuaryNarrative.gd:177:Virelai", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 177, "speaker": "Virelai", "portrait": "portrait_virelai.png", "telepathic": false, "text": "Neither Anna nor I demand you forget the dead, %s. Only look with clear eyes—and beware those who pay gold to keep wild skies silent."}, {"id": "SanctuaryNarrative.gd:178:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 178, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "...Fair enough. Keep an eye on me up on that shoulder-rig today, alright?"}, {"id": "SanctuaryNarrative.gd:184:Virelai", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 184, "speaker": "Virelai", "portrait": "portrait_virelai.png", "telepathic": false, "text": "Your new charge sleeps peacefully above those beech-coals, %s. Neither Hendrick nor any cold vault will touch its shell while my wing covers the stand. Go see what mischief stirs inside Bruges."}, {"id": "SanctuaryNarrative.gd:189:Virelai", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 189, "speaker": "Virelai", "portrait": "portrait_virelai.png", "telepathic": false, "text": "Five winters since a glaring boy tied my first brass snap-ring without blinking. You belong in the harness now, %s."}, {"id": "SanctuaryNarrative.gd:197:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 197, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Old Hendrick says he's short leather on the south bench, and Virelai's shoulder-ring still wants a proper splice before dusk."}, {"id": "SanctuaryNarrative.gd:201:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 201, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Virelai's ring is solid. Maren's still fussing over her northern kettle, and that rescued Silver-Slate courier across the gorge is still tangled in hunter iron until someone breaks her loose."}, {"id": "SanctuaryNarrative.gd:205:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 205, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "You dressed Kestrel's torn wing and stopped flinching when Virelai breathes near you."}, {"id": "SanctuaryNarrative.gd:206:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 206, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Doesn't mean I belong here. As soon as winter breaks, I want word on Clara."}, {"id": "SanctuaryNarrative.gd:207:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 207, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "And we've scouts watching every eastern road. Until we locate those hunter wagons, learn the clouds with us—no twelve-year-old rides a storm-sortie raw."}, {"id": "SanctuaryNarrative.gd:212:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 212, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Wind's shifting off the sea. Matthijs went over the east gorge trying to string a fresh gale-pennant before patrol."}, {"id": "SanctuaryNarrative.gd:216:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 216, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Streams read clean off the point. Virelai's left wing-hinge still has crusted sea-salt chafing under the bronze buckle if you've a damp cloth handy."}, {"id": "SanctuaryNarrative.gd:220:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 220, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Not with Virelai eyeing an empty rack like that! Stockman Joost's out by the sheepfold if you've strong wrists for a cleaver."}, {"id": "SanctuaryNarrative.gd:224:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 224, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Two winters in the harness drill paid off, %s. Ready to man Virelai's forward bolt-rig above the Flemish coast?"}, {"id": "SanctuaryNarrative.gd:225:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 225, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Hooks locked and belt cinch doubled. Take us up, Captain!"}, {"id": "SanctuaryNarrative.gd:232:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 232, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Maren and I won't let Hendrick take your egg to the cold vaults while the coals are lit. Take the West Cliff Trail down into the Walled City of Bruges and find out what major action the Church is staging."}, {"id": "SanctuaryNarrative.gd:237:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 237, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Don't climb into thunderheads in your old wool tunic—Matthijs and Hendrick left your fitted Flight-Jerkin beside the map table."}, {"id": "SanctuaryNarrative.gd:241:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 241, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Heavy storm-headwinds over the ridge today, %s. Visit Stockman Joost to butcher fresh mutton onto Virelai's rack before we mount up for Storm Recon."}, {"id": "SanctuaryNarrative.gd:246:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 246, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Five years since we hauled you out of a Bruges alley, %s. You can splice a carabiner blindfolded in crosswinds."}, {"id": "SanctuaryNarrative.gd:247:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 247, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Lightning's banking hard over the eastern border ridge, and scouts caught a Crimson Acid-Spitter tangled near Church outriders. Climb aboard Virelai—stay tight on that forward strap."}, {"id": "SanctuaryNarrative.gd:254:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 254, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Touchdown clear on the perch! Not half bad for fourteen years old on your first live sortie!"}, {"id": "SanctuaryNarrative.gd:255:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 255, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "...She wheeled smooth whenever I sighted down a ballista barrel. Never knew a dragon watched her own rigman like a sister watches a helm."}, {"id": "SanctuaryNarrative.gd:256:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 256, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "She's listening to you, %s—season after season, gale after gale. Keep flying beside us."}, {"id": "SanctuaryNarrative.gd:267:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 267, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Topman's Speed-Splice Board: whip and lock a full Brotherhood Harness Splice before the sand drops cleanly. Beat the post and wear my brass Timing Ring permanently."}, {"id": "SanctuaryNarrative.gd:279:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 279, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Crack shot under pressure! Slide that brass Timing Ring onto your right thumb—every mid-air splice from today onward comes faster and cleaner."}, {"id": "SanctuaryNarrative.gd:282:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 282, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Bobbled a half-hitch on the turn! Step up again whenever you want another run at the Timing Ring."}, {"id": "SanctuaryNarrative.gd:288:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 288, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Still lightning-quick, Topman! Keep those wrists warm for gale weather."}, {"id": "SanctuaryNarrative.gd:300:Bellman Matthijs", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 300, "speaker": "Bellman Matthijs", "portrait": "portrait_matthijs.png", "telepathic": false, "text": "Hah! One scrap fish from the hearth and she remembers your sleeve forever. No creature holds loyalty finer than a Silver-Slate courier."}, {"id": "SanctuaryNarrative.gd:312:Camp Cook Mieke", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 312, "speaker": "Camp Cook Mieke", "portrait": "portrait_cook.png", "telepathic": false, "text": "Mind the kettle steam, dock-lad! Mutton pottage and barley bread stay hot on the long oak tables from noon bell till twilight watch."}, {"id": "SanctuaryNarrative.gd:313:%PLAYER%", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 313, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Didn't think outlaw dragon-folk kept two whole trestles just for dinner."}, {"id": "SanctuaryNarrative.gd:314:Camp Cook Mieke", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 314, "speaker": "Camp Cook Mieke", "portrait": "portrait_cook.png", "telepathic": false, "text": "Harness-men, scouts, and chirurgeons starve just as quick as dockworkers, boy. Grab a trencher whenever your knees shake from climbing rocks."}, {"id": "SanctuaryNarrative.gd:318:Camp Cook Mieke", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 318, "speaker": "Camp Cook Mieke", "portrait": "portrait_cook.png", "telepathic": false, "text": "Look at how fast you sprout! Two winters ago you stood hunched by the post scowling at my stew ladle—now you lick the wooden bowl dry before Hendrick finishes grace."}, {"id": "SanctuaryNarrative.gd:322:Camp Cook Mieke", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 322, "speaker": "Camp Cook Mieke", "portrait": "portrait_cook.png", "telepathic": false, "text": "Whole mess-yard heard you and Old Hendrick barking over that black-and-gold egg! Wrap some rye bread under your cloak before walking into Bruges tonight—Church bailiffs have sharpened every pike along the gates."}, {"id": "SanctuaryNarrative.gd:326:Camp Cook Mieke", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 326, "speaker": "Camp Cook Mieke", "portrait": "portrait_cook.png", "telepathic": false, "text": "Beef broth and hard Damme cheese packed for high altitude, %s. Drink deep before Anna whistles mount-up—storm air steals heat straight through oiled leather."}, {"id": "SanctuaryNarrative.gd:334:Stockman Joost", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 334, "speaker": "Stockman Joost", "portrait": "portrait_herdsman.png", "telepathic": false, "text": "Easy around the rails—no sudden waving near the pied bullocks. Keeping dragons secret on this ridge means hiding an appetite bigger than twenty plow-horses."}, {"id": "SanctuaryNarrative.gd:335:Stockman Joost", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 335, "speaker": "Stockman Joost", "portrait": "portrait_herdsman.png", "telepathic": false, "text": "Cousins near Sluis smuggle ewes and old oxen up our back sheep-track after moonset. One beef quarter on Virelai's rack keeps her wing-muscles strong without torching a farmer's fold."}, {"id": "SanctuaryNarrative.gd:340:Stockman Joost", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 340, "speaker": "Stockman Joost", "portrait": "portrait_herdsman.png", "telepathic": false, "text": "Even the ewes looked up when Hendrick started yelling about taking that black egg away from you! Keep your collar high inside Bruges's walls, %s—scouts swear half the Catchpoles in Flanders rode in before dusk."}, {"id": "SanctuaryNarrative.gd:346:Stockman Joost", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 346, "speaker": "Stockman Joost", "portrait": "portrait_herdsman.png", "telepathic": false, "text": "Clean quartering already done, lad! Carry that mutton joint back over the timber bridge and hang it on Virelai's Butcher Rack west of her perch."}, {"id": "SanctuaryNarrative.gd:350:Stockman Joost", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 350, "speaker": "Stockman Joost", "portrait": "portrait_herdsman.png", "telepathic": false, "text": "Set down whatever your hands are full with first—takes two steady wrists on the cleaver handle to portion dragon-rations cleanly."}, {"id": "SanctuaryNarrative.gd:355:Stockman Joost", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 355, "speaker": "Stockman Joost", "portrait": "portrait_herdsman.png", "telepathic": false, "text": "intro_line"}, {"id": "SanctuaryNarrative.gd:365:Stockman Joost", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 365, "speaker": "Stockman Joost", "portrait": "portrait_herdsman.png", "telepathic": false, "text": "Dead on every seam—no bone splinters! Bring that quarter over to Virelai's rack before the crows smell blood."}, {"id": "SanctuaryNarrative.gd:372:Stockman Joost", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 372, "speaker": "Stockman Joost", "portrait": "portrait_herdsman.png", "telepathic": false, "text": "Lambing went quiet this spring and not one Church bailiff sniffed our smoke. Watch how sleek Virelai's flanks stay when she's fed proper pasture mutton."}, {"id": "SanctuaryNarrative.gd:376:Stockman Joost", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 376, "speaker": "Stockman Joost", "portrait": "portrait_herdsman.png", "telepathic": false, "text": "Five winters since you jumped at a sheep-dog barking behind my barn! Pasture gates are latched tight for tonight's gale, topman—fly safe above those black clouds."}, {"id": "SanctuaryNarrative.gd:400:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 400, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Look at her crests lift—well portioned, %s. Whenever you're ready at the harness board, patrol's yours to whistle off."}, {"id": "SanctuaryNarrative.gd:414:Brotherhood Scout", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 414, "speaker": "Brotherhood Scout", "portrait": "portrait_brotherhood.png", "telepathic": false, "text": "Iron-shod wagons and Church horns have been crowding the South Port Gate of Bruges City since sunset. Something major's brewing behind those ramparts."}, {"id": "SanctuaryNarrative.gd:418:Brotherhood Scout", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryNarrative.gd", "line": 418, "speaker": "Brotherhood Scout", "portrait": "portrait_brotherhood.png", "telepathic": false, "text": "Fog lies thick over the bridge gorge tonight—no patrol lanterns moving along the polder dyke below. Crew bunkhouse and pastures rest easy behind the mist."}, {"id": "SanctuaryRegion.gd:377:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryRegion.gd", "line": 377, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Meet back by Virelai's perch when you've finished drying your boots, %s."}, {"id": "SanctuaryRegion.gd:580:Saddler Hendrick", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryRegion.gd", "line": 580, "speaker": "Saddler Hendrick", "portrait": "portrait_hendrick.png", "telepathic": false, "text": "Not so fast—without cured wyrm-hide on my bench I've got no waxed straps to rebuild that ring with."}, {"id": "SanctuaryRegion.gd:607:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryRegion.gd", "line": 607, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Clean dressing—even waxed the turn like a guild rigger. Sister Maren's over by the north kettle if you've a mind to help."}, {"id": "SanctuaryRegion.gd:609:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryRegion.gd", "line": 609, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Good work. Sister Maren's tending something hot by the north rocks—might see if she needs a hand."}, {"id": "SanctuaryRegion.gd:628:Bellman Matthijs", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryRegion.gd", "line": 628, "speaker": "Bellman Matthijs", "portrait": "portrait_matthijs.png", "telepathic": false, "text": "Look at that green Brotherhood swallowtail stream out! East gusts twenty knots—clean flying weather."}, {"id": "SanctuaryRegion.gd:629:Bellman Matthijs", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryRegion.gd", "line": 629, "speaker": "Bellman Matthijs", "portrait": "portrait_matthijs.png", "telepathic": false, "text": "Hear Anna's checking salt crust on Virelai's left wing-hinge back west before patrol lifts."}, {"id": "SanctuaryRegion.gd:637:Captain Anna", "kind": "dialogue", "region": "Brotherhood Sanctuary (Ch. 2/4)", "file": "scripts/regions/SanctuaryRegion.gd", "line": 637, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Hold up—Virelai won't haul two men through a sea-gale on an empty stomach. Check with Stockman Joost out by the sheepfold before we strap in."}, {"id": "VirelaiConvoyRaidRegion.gd:87:Captain Anna", "kind": "dialogue", "region": "Virelai Convoy Raid (Book II)", "file": "scripts/regions/VirelaiConvoyRaidRegion.gd", "line": 87, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Three iron blood-harvest barges below the mist, Virelai! Snap their boom-chains, dodge those Ward-Bell rings, and tear the cages open!"}, {"id": "VirelaiConvoyRaidRegion.gd:256:Virelai", "kind": "dialogue", "region": "Virelai Convoy Raid (Book II)", "file": "scripts/regions/VirelaiConvoyRaidRegion.gd", "line": 256, "speaker": "Virelai", "portrait": "portrait_virelai.png", "telepathic": false, "text": "Every river chain snapped and all three harvest cages smashed clean! Those captive drakes are clearing the southern mist!"}, {"id": "VirelaiConvoyRaidRegion.gd:257:Captain Anna", "kind": "dialogue", "region": "Virelai Convoy Raid (Book II)", "file": "scripts/regions/VirelaiConvoyRaidRegion.gd", "line": 257, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Fly straight for Hesbaye, Kestrel—bring that supply satchel to my nephew and keep him alive till I break east!"}, {"id": "VirelaiFlightCutscene.gd:90:Captain Anna", "kind": "dialogue", "region": "Virelai Flight Sorties (Ch. 2)", "file": "scripts/regions/VirelaiFlightCutscene.gd", "line": 90, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Ridge convoy routed—wait! Eyes high over the black storm wall!!"}, {"id": "VirelaiFlightCutscene.gd:122:%PLAYER%", "kind": "dialogue", "region": "Virelai Flight Sorties (Ch. 2)", "file": "scripts/regions/VirelaiFlightCutscene.gd", "line": 122, "speaker": "%PLAYER%", "portrait": "portrait_boy_angry.png", "telepathic": false, "text": "My waist-strap!!"}, {"id": "VirelaiFlightCutscene.gd:123:Captain Anna", "kind": "dialogue", "region": "Virelai Flight Sorties (Ch. 2)", "file": "scripts/regions/VirelaiFlightCutscene.gd", "line": 123, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "%s!! Grab the tail-line—HOLD ON!!"}, {"id": "VirelaiFlightRegion.gd:128:Captain Anna", "kind": "dialogue", "region": "Virelai Flight Sorties (Ch. 2)", "file": "scripts/regions/VirelaiFlightRegion.gd", "line": 128, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Coast clear above the sea-cliffs! Thread those glowing wind-updrafts to build speed, keep your quarry bolts steady on those two ballista carts, and roll tight if a red sightline locks on!"}, {"id": "VirelaiFlightRegion.gd:134:Captain Anna", "kind": "dialogue", "region": "Virelai Flight Sorties (Ch. 2)", "file": "scripts/regions/VirelaiFlightRegion.gd", "line": 134, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Storm clouds stacked thick over the border ridge! Dive inside dark cloud banks whenever a ballista locks on, knock loose that trapped Acid-Spitter's net, and keep your grip fast on the strap!"}, {"id": "VirelaiFlightRegion.gd:247:Captain Anna", "kind": "dialogue", "region": "Virelai Flight Sorties (Ch. 2)", "file": "scripts/regions/VirelaiFlightRegion.gd", "line": 247, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Strap locked tight mid-gale! That's a true Brotherhood rigger, %s!"}, {"id": "VirelaiFlightRegion.gd:496:Captain Anna", "kind": "dialogue", "region": "Virelai Flight Sorties (Ch. 2)", "file": "scripts/regions/VirelaiFlightRegion.gd", "line": 496, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Watch your eyes—that Crimson Acid-Spitter just washed a hunter cart clean off the ridge with her venom! Glide close enough to sketch her markings in your Bestiary!"}, {"id": "VirelaiFlightRegion.gd:513:Captain Anna", "kind": "dialogue", "region": "Virelai Flight Sorties (Ch. 2)", "file": "scripts/regions/VirelaiFlightRegion.gd", "line": 513, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Hold fast—the port saddle-buckle just parted in that crosswind! I'm climbing into high cover while you re-lash the ring!"}, {"id": "VirelaiFlightRegion.gd:526:Captain Anna", "kind": "dialogue", "region": "Virelai Flight Sorties (Ch. 2)", "file": "scripts/regions/VirelaiFlightRegion.gd", "line": 526, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Quarrel nicked our port ring! Climbing above the line while you splice it tight!"}, {"id": "VirelaiFlightRegion.gd:571:Captain Anna", "kind": "dialogue", "region": "Virelai Flight Sorties (Ch. 2)", "file": "scripts/regions/VirelaiFlightRegion.gd", "line": 571, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Both carts in splinters and that Ochre Gale-Wing's climbing seaward with clear skies ahead! Ready to bank back to the Sanctuary perch?"}, {"id": "VirelaiFlightRegion.gd:572:%PLAYER%", "kind": "dialogue", "region": "Virelai Flight Sorties (Ch. 2)", "file": "scripts/regions/VirelaiFlightRegion.gd", "line": 572, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "...Didn't feel half as stiff in the rig that time. Lead back west, Anna."}, {"id": "WatchtowerHearthRegion.gd:109:Watchtower Lookout", "kind": "dialogue", "region": "Watchtower Hearth (Ch. 3)", "file": "scripts/regions/WatchtowerHearthRegion.gd", "line": 109, "speaker": "Watchtower Lookout", "portrait": "portrait_watchman.png", "telepathic": false, "text": "By the Saints—is that Captain Anna's forward rigman? We fired pine-pitch flares two nights running after Virelai came in torn up!"}, {"id": "WatchtowerHearthRegion.gd:110:%PLAYER%", "kind": "dialogue", "region": "Watchtower Hearth (Ch. 3)", "file": "scripts/regions/WatchtowerHearthRegion.gd", "line": 110, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Wait—Anna made it back from the storm? Quick, make room beside the stove—this black egg's mother died shielding it in the hollow, and it went cold in the frost!"}, {"id": "WatchtowerHearthRegion.gd:111:Watchtower Lookout", "kind": "dialogue", "region": "Watchtower Hearth (Ch. 3)", "file": "scripts/regions/WatchtowerHearthRegion.gd", "line": 111, "speaker": "Watchtower Lookout", "portrait": "portrait_watchman.png", "telepathic": false, "text": "Down onto the wool blanket, right against the iron grate! I'll rake fresh spruce coals underneath."}, {"id": "WatchtowerHearthRegion.gd:214:Captain Anna", "kind": "dialogue", "region": "Watchtower Hearth (Ch. 3)", "file": "scripts/regions/WatchtowerHearthRegion.gd", "line": 214, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "There you are, %s! Virelai and I have been sweeping the pine ridges since the storm broke—thought that black dragon dragged you into the ravine!"}, {"id": "WatchtowerHearthRegion.gd:215:%PLAYER%", "kind": "dialogue", "region": "Watchtower Hearth (Ch. 3)", "file": "scripts/regions/WatchtowerHearthRegion.gd", "line": 215, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Wait—she wasn't hunting us! Hunter ballista bolts had torn her flank open. She died shielding this egg beneath her wing, and I followed your Border Chart straight here to the fire."}, {"id": "WatchtowerHearthRegion.gd:216:Watchtower Lookout", "kind": "dialogue", "region": "Watchtower Hearth (Ch. 3)", "file": "scripts/regions/WatchtowerHearthRegion.gd", "line": 216, "speaker": "Watchtower Lookout", "portrait": "portrait_watchman.png", "telepathic": false, "text": "Look at the heat coming off it now, Captain—pitch-black shell with gold seams warming right through, completely unbroken."}, {"id": "WatchtowerHearthRegion.gd:217:Captain Anna", "kind": "dialogue", "region": "Watchtower Hearth (Ch. 3)", "file": "scripts/regions/WatchtowerHearthRegion.gd", "line": 217, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "An unrecorded black breed... And Church hounds are already combing the border woods below us. Wrap it in my wool cloak and climb onto Virelai's shoulder-rig—we're flying you straight back to the main Sanctuary outpost near Bruges!"}, {"id": "WatchtowerHearthRegion.gd:263:Captain Anna", "kind": "dialogue", "region": "Watchtower Hearth (Ch. 3)", "file": "scripts/regions/WatchtowerHearthRegion.gd", "line": 263, "speaker": "Captain Anna", "portrait": "portrait_anna.png", "telepathic": false, "text": "Virelai's wings are strapped and ready on the terrace—wind's fair back to the Bruges Sanctuary. Hold tight to that black-and-gold egg."}, {"id": "WillemHouseRegion.gd:81:Uncle Willem", "kind": "dialogue", "region": "Uncle Willem's Cottage (Ch. 1)", "file": "scripts/regions/WillemHouseRegion.gd", "line": 81, "speaker": "Uncle Willem", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Hold on, officer—he's half out of his wits looking for his sister! I'll keep him by the hearth... Now stay low behind the barrels if you slip back out, lad (%d/%d HP)."}, {"id": "WillemHouseRegion.gd:88:Uncle Willem", "kind": "dialogue", "region": "Uncle Willem's Cottage (Ch. 1)", "file": "scripts/regions/WillemHouseRegion.gd", "line": 88, "speaker": "Uncle Willem", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Evening, %s. Set the loaf by the hearth and scrub the salt off your hands before supper."}, {"id": "WillemHouseRegion.gd:89:Clara", "kind": "dialogue", "region": "Uncle Willem's Cottage (Ch. 1)", "file": "scripts/regions/WillemHouseRegion.gd", "line": 89, "speaker": "Clara", "portrait": "portrait_clara.png", "telepathic": false, "text": "Sit a spell if your legs aren't giving out—pottage is still hot."}, {"id": "WillemHouseRegion.gd:163:Uncle Willem", "kind": "dialogue", "region": "Uncle Willem's Cottage (Ch. 1)", "file": "scripts/regions/WillemHouseRegion.gd", "line": 163, "speaker": "Uncle Willem", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Check by the threshold—something caught on the sill when the door swung open!"}, {"id": "WillemHouseRegion.gd:167:Uncle Willem", "kind": "dialogue", "region": "Uncle Willem's Cottage (Ch. 1)", "file": "scripts/regions/WillemHouseRegion.gd", "line": 167, "speaker": "Uncle Willem", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Saw the Church herald whipping up a crowd by the square again. Keep clear of his pulpit, %s."}, {"id": "WillemHouseRegion.gd:168:Uncle Willem", "kind": "dialogue", "region": "Uncle Willem's Cottage (Ch. 1)", "file": "scripts/regions/WillemHouseRegion.gd", "line": 168, "speaker": "Uncle Willem", "portrait": "portrait_uncle.png", "telepathic": false, "text": "Folks in Louvain swore a wild dragon caught your parents in Old Heverlee woods, yet your father's iron quiver came home sheared by forged steel—no scorch marks anywhere. Let buried ashes rest, %s, and look after your sister."}, {"id": "WillemHouseRegion.gd:182:%PLAYER%", "kind": "dialogue", "region": "Uncle Willem's Cottage (Ch. 1)", "file": "scripts/regions/WillemHouseRegion.gd", "line": 182, "speaker": "%PLAYER%", "portrait": "portrait_boy_neutral.png", "telepathic": false, "text": "Here—fished this out of the eddy by the north pilings. Yours?"}, {"id": "WillemHouseRegion.gd:183:Clara", "kind": "dialogue", "region": "Uncle Willem's Cottage (Ch. 1)", "file": "scripts/regions/WillemHouseRegion.gd", "line": 183, "speaker": "Clara", "portrait": "portrait_clara.png", "telepathic": false, "text": "My oilskin pouch! Look—Mother's Louvain brass thimble was still wrapped inside. Keep it, %s, and rub this beeswax into your hemp lines."}, {"id": "WillemHouseRegion.gd:188:Clara", "kind": "dialogue", "region": "Uncle Willem's Cottage (Ch. 1)", "file": "scripts/regions/WillemHouseRegion.gd", "line": 188, "speaker": "Clara", "portrait": "portrait_clara.png", "telepathic": false, "text": "Heard the shouting in the square from halfway down the lane, didn't you? You always go dead quiet when the Hunters come up."}, {"id": "WillemHouseRegion.gd:189:Clara", "kind": "dialogue", "region": "Uncle Willem's Cottage (Ch. 1)", "file": "scripts/regions/WillemHouseRegion.gd", "line": 189, "speaker": "Clara", "portrait": "portrait_clara.png", "telepathic": false, "text": "Climb into the straw, %s. Dawn tide doesn't wait for sore shoulders."}, {"id": "WillemHouseRegion.gd:277:Uncle Willem", "kind": "dialogue", "region": "Uncle Willem's Cottage (Ch. 1)", "file": "scripts/regions/WillemHouseRegion.gd", "line": 277, "speaker": "Uncle Willem", "portrait": "portrait_uncle.png", "telepathic": false, "text": "%s! Up—get up now! Clara's pallet hasn't been touched, and the front latch is unbarred!"}, {"id": "ItemCatalog.gd:11:Heavy Harbor Cargo", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 11, "speaker": "Heavy Harbor Cargo", "portrait": "icon_crate.png", "telepathic": false, "text": "Salt-cured North Sea herring bound for Quartermaster Vos's storehouse. Demands both hands to carry; you cannot sprint cleanly until it is set down."}, {"id": "ItemCatalog.gd:17:Unseen Dragon Relic", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 17, "speaker": "Unseen Dragon Relic", "portrait": "icon_egg.png", "telepathic": false, "text": "Pitch-black shell streaked with faint molten-gold veins, shielded beneath a dying mother's wing. Heavy and fever-warm—the Ghent Elders want it locked away, and the Church just cried a bounty on it."}, {"id": "ItemCatalog.gd:23:Captured Ambush Note", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 23, "speaker": "Captured Ambush Note", "portrait": "icon_strap.png", "telepathic": false, "text": "Crumpled parchment dropped by Church Catchpoles beside the Counting-House iron-chain wagon: \"...the hollow nest was cold and the egg already taken. Meet Father Anselm at St. Donatian's by the eighth evening bell...\""}, {"id": "ItemCatalog.gd:29:Navigator's Instrument", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 29, "speaker": "Navigator's Instrument", "portrait": "icon_compass.png", "telepathic": false, "text": "Bruges mariner's needle housed in tarnished brass. Helps keep true bearings through the Zwin docks and the wild borderlands beyond Old Heverlee."}, {"id": "ItemCatalog.gd:35:Ropewalk Blessing (Passive)", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 35, "speaker": "Ropewalk Blessing (Passive)", "portrait": "icon_beeswax_thimble.png", "telepathic": false, "text": "Your mother's Louvain beeswax cake and pitted thimble, kept by Clara. Grants +1 Max Knot Integrity (4 loops), +25% Gold Cinch Zone, and +20% rope cast reach."}, {"id": "ItemCatalog.gd:41:Ropewalk Tool & Clue", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 41, "speaker": "Ropewalk Tool & Clue", "portrait": "icon_shuttle.png", "telepathic": false, "text": "Clara's polished boxwood and brass shuttle from the Bruges Ropewalk—found fallen with torn cordage outside the silent mill."}, {"id": "ItemCatalog.gd:47:Oiled Harness Evidence", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 47, "speaker": "Oiled Harness Evidence", "portrait": "icon_strap.png", "telepathic": false, "text": "Heavy double-stitched wyrm-hide strap cut from a secret rider's flight rig, tied off with a clean Ropewalk bend instead of Hunter knots."}, {"id": "ItemCatalog.gd:53:Brotherhood Crew Coat", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 53, "speaker": "Brotherhood Crew Coat", "portrait": "icon_jerkin.png", "telepathic": false, "text": "Oiled wyrm-hide and forest-green flight jerkin stitched by Hendrick over five winters. Fitted with brass carabiner rings for upper-cloud patrol."}, {"id": "ItemCatalog.gd:59:Chirurgeon's Salve", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 59, "speaker": "Chirurgeon's Salve", "portrait": "icon_poultice.png", "telepathic": false, "text": "Sister Maren's cool cliffsage, tallow, and honey poultice used to soothe rope-burns under a dragon's wing-hinge."}, {"id": "ItemCatalog.gd:65:Brotherhood Rigging Gear", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 65, "speaker": "Brotherhood Rigging Gear", "portrait": "icon_carabiner.png", "telepathic": false, "text": "Forged brass-and-steel quick-link snapped onto Virelai's shoulder harness so mid-flight splices lock before a dive can shear the belly-band."}, {"id": "ItemCatalog.gd:71:Topman's Speed-Knot Award", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 71, "speaker": "Topman's Speed-Knot Award", "portrait": "icon_carabiner.png", "telepathic": false, "text": "Burnished brass splice-ring awarded at Hendrick's gorge training board. Steadying your wrist permanently grants +18% Gold Cinch Zone and +2.0s on every knot tie."}, {"id": "ItemCatalog.gd:77:Splicing & Grappling Kit", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 77, "speaker": "Splicing & Grappling Kit", "portrait": "icon_hook_whip.png", "telepathic": false, "text": "Tinned mariner's hook and tarred whipping twine used to bind split beams, haul heavy rigging, or snatch timber rings."}, {"id": "ItemCatalog.gd:83:Canal Provisions", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 83, "speaker": "Canal Provisions", "portrait": "icon_biscuit_twine.png", "telepathic": false, "text": "Hard-baked ship's biscuit stowed beside a spare coil of light hemp line for emergency splices on the wharf."}, {"id": "ItemCatalog.gd:89:Cordage Bundle", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 89, "speaker": "Cordage Bundle", "portrait": "icon_hemp_bundle.png", "telepathic": false, "text": "Freshly combed Flanders hemp washed ashore in crates—valued by every quartermaster and sailor along the quay."}, {"id": "ItemCatalog.gd:95:Warm Supper Loaf", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 95, "speaker": "Warm Supper Loaf", "portrait": "icon_bread.png", "telepathic": false, "text": "Crusty evening rye loaf baked by Pieter in Bruges Market, brought home to Uncle Willem and Clara before dusk."}, {"id": "ItemCatalog.gd:101:Brotherhood Chart [M]", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 101, "speaker": "Brotherhood Chart [M]", "portrait": "icon_map.png", "telepathic": false, "text": "Vellum border survey charting safe cairn trails, frost dead-ends, briar thickets, and winched creek crossings toward the Outpost."}, {"id": "ItemCatalog.gd:107:Abbey Scriptorium Evidence", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 107, "speaker": "Abbey Scriptorium Evidence", "portrait": "icon_strap.png", "telepathic": false, "text": "Signed Church Decree ordering Inquisitors to bury the Old Heverlee Shrine Key affair—paired with a five-year requisition sending 'Clara of Bruges, rig-master' east to Namur's quarries."}, {"id": "ItemCatalog.gd:113:Dijle Foundry Clay", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 113, "speaker": "Dijle Foundry Clay", "portrait": "icon_clay.png", "telepathic": false, "text": "Fine grey alluvial clay dug along the Dijle bank to seal the hairline fracture in Master Pieter's cracked bell-mould."}, {"id": "ItemCatalog.gd:119:Old Heverlee Relic", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 119, "speaker": "Old Heverlee Relic", "portrait": "icon_carabiner.png", "telepathic": false, "text": "Tarnished guild brass signet recovered for the one-eyed Old Heverlee survivor—bearing the same oak-and-hound stamp as your parents' field kit."}, {"id": "ItemCatalog.gd:125:Stealth Distraction", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 125, "speaker": "Stealth Distraction", "portrait": "prop_resonance_chime.png", "telepathic": false, "text": "Harmonic hand-cast bronze chime from the Louvain Foundry; drop or ring it near patrols to draw Catchpoles out of lanes."}, {"id": "ItemCatalog.gd:131:Alchemical Cover", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 131, "speaker": "Alchemical Cover", "portrait": "prop_smoke_pellet.png", "telepathic": false, "text": "Beeswaxed ash-and-herb pellet steeped by Louvain's Dyers' Quarter herbalist; bursts into concealing soot-fog for five seconds."}, {"id": "ItemCatalog.gd:137:Catacombs Secret Relic", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 137, "speaker": "Catacombs Secret Relic", "portrait": "prop_treasure_chest_closed.png", "telepathic": false, "text": "Ruby-sealed Brotherhood reliquary unearthed beneath the eastern Chalice tomb in St. Peter's Crypt—fortified your vitality (+1 Max Heart) and deepened your bond."}, {"id": "ItemCatalog.gd:143:Sint-Pieterskerk Quarry Load", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 143, "speaker": "Sint-Pieterskerk Quarry Load", "portrait": "icon_mason_stone.png", "telepathic": false, "text": "Heavy bundle of white Gobertange ashlar blocks unlashed from Vismarkt Stone Quay for Master Mason Matthijs's tower race against Brussels."}, {"id": "ItemCatalog.gd:149:Guild Master Craft Signet", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 149, "speaker": "Guild Master Craft Signet", "portrait": "icon_plumb_signet.png", "telepathic": false, "text": "Gilded mason's plumb-bob awarded by Master Mason Matthijs once Sint-Pieterskerk's limestone spire rose higher than Brussels' belfry."}, {"id": "ItemCatalog.gd:155:Golden Shrine Key Relic", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 155, "speaker": "Golden Shrine Key Relic", "portrait": "icon_heverlee_key.png", "telepathic": false, "text": "Ancient double-warded bronze and gold key your parents died hiding beneath Old Heverlee Woods to keep the Devildragon sealed."}, {"id": "ItemCatalog.gd:161:Inquisitor Field Dispatch", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 161, "speaker": "Inquisitor Field Dispatch", "portrait": "icon_strap.png", "telepathic": false, "text": "Wax-stamped Church hunting order recovered from the Old Heverlee scout ridge naming Namur's Quarry and the Meuse blood-barge convoy."}, {"id": "ItemCatalog.gd:167:Brotherhood Courier Drop", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 167, "speaker": "Brotherhood Courier Drop", "portrait": "icon_hemp_bundle.png", "telepathic": false, "text": "Captain Anna's stitched leather dispatch pack filled with dried river rations, tarred hemp, and Ember-tallow for Hesbaye."}, {"id": "ItemCatalog.gd:172:Satchel Item", "kind": "item", "region": "Item Lore Catalog", "file": "scripts/data/ItemCatalog.gd", "line": 172, "speaker": "Satchel Item", "portrait": "icon_knot.png", "telepathic": false, "text": "Carried field possession stored safely inside your oilskin dock satchel."}];
window.STUDIO_SPEAKERS = ["%DRAGON%", "%PLAYER%", "Anna", "Archivist Ledger Index (1431)", "Bailiff Guard", "Baker Pieter", "Baker's Wife", "Barge Skipper", "Barrelmaker", "Beadle Hendrik", "Beguine Sister", "Bell-Founder Pieter", "Bellman Matthijs", "Brotherhood Scout", "Camp Cook Mieke", "Captain Anna", "Catchpole Sergeant", "Chained Decree — Anno 1422 (9 Years Past)", "Church Inquisitor", "Citadel Patrol", "Clara", "Cloister Brother", "Cloth Runner", "Customsman Dirk", "Dockhand Jan", "Dockhand Piet", "Dropped Ambush Note", "East Gatehouse Post", "Factor Joris", "Faded Brabant Notice", "Father Anselm", "Gate Pikeman", "Gatewarden Maerten", "Goodwife Trude", "Guildmistress Aleidis", "Harbor Decree", "Harbor Gatehouse Post", "Herb Gatherer", "Hooded Brotherhood Rider", "Inquisitor Field Dispatch", "Ledger — Anno 1422", "Loom Apprentice", "Master Draper", "Master Mason Matthijs", "Milepost & Church Notice", "Namur Requisition Warrant — Anno 1426 (5 Years Past)", "North Tapestry — The Prior's Coffer", "Novice Clerk", "Outpost Scout", "Parish Folio — Anno %s", "Quartermaster Vos", "Ropewalk Braider", "Saddler Hendrick", "Saddler Matthijs", "Shipmaster Hendrik", "Sister Beatrijs", "Sister Katelijne", "Sister Maren", "South Gate Watch", "South Gatehouse Post", "South Post Sign", "Stockman Joost", "String(n.get(\"speaker\"", "String(src[\"name\"])", "String(tf[\"name\"])", "Swan Patron", "Tollkeeper", "Towpath Milestone", "Uncle Willem", "Veteran Martijn", "Virelai", "Warrant — Anno 1426", "Watchtower Lookout", "West Tapestry — Of the Stag", "Wharf Porter", "title_str"];
